import TimesIcon from '@patternfly/react-icons/dist/esm/icons/times-icon';
import { useState } from 'react';

interface PrototypeBannerProps {
  jiraId: string;
  jiraUrl: string;
  title: string;
}

export function PrototypeBanner({ jiraId, jiraUrl, title }: Readonly<PrototypeBannerProps>) {
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;
  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: '50%',
        transform: 'translateX(-50%)',
        width: 'auto',
        whiteSpace: 'nowrap',
        zIndex: 9999,
        backgroundColor: '#f0ab00',
        color: '#1b1d21',
        borderRadius: '0 0 8px 8px',
        padding: '4px 12px',
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        fontSize: '12px',
        lineHeight: 1.5,
      }}
    >
      <span>
        <strong>
          UX Prototype —{' '}
          <a
            href={jiraUrl}
            target="_blank"
            rel="noreferrer"
            style={{ color: '#1b1d21', textDecoration: 'underline', fontWeight: 500 }}
          >
            {jiraId}
          </a>
        </strong>
        {'  ·  '}
        {title}
        {'  ·  '}
        All data is mocked, no real backend{'  ·  '}Form submissions reset on page refresh
      </span>
      <button
        onClick={() => setDismissed(true)}
        aria-label="Dismiss prototype notice"
        style={{
          background: 'none',
          border: 'none',
          cursor: 'pointer',
          padding: '2px',
          color: '#1b1d21',
          flexShrink: 0,
          display: 'flex',
          alignItems: 'center',
        }}
      >
        <TimesIcon />
      </button>
    </div>
  );
}
