import {
  CopyCell,
  DateTimeCell,
  LoadingPage,
  PageDetail,
  PageDetails,
  TextCell,
} from '@ansible/ansible-ui-framework';
import { StatusCell } from '@ansible/common-ui/Status';
import { Label, LabelGroup } from '@patternfly/react-core';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';
import { useRegisterPrototypeNotes } from '../../../../../platform/common/PrototypeNotesRegistry';
import { RegistriesDetailsPrototypeNote } from '../../../../../platform/src/prototype/registries/RegistriesDetailsPrototypeNotes';
import { HubError } from '../../../common/HubError';
import { hubAPI } from '../../../common/api/formatPath';
import { HubItemsResponse } from '../../../common/useHubView';
import { RemoteRegistry } from '../RemoteRegistry';
import { isRegistriesPrototypeMode } from '../registriesLabels';

function formatSyncSchedule(
  schedule: RemoteRegistry['sync_schedule'],
  t: (key: string) => string
) {
  switch (schedule) {
    case 'daily':
      return t('Daily');
    case 'weekly':
      return t('Weekly');
    case 'custom':
      return t('Custom');
    case 'manual':
      return t('Manual');
    default:
      return t('Not configured');
  }
}

function formatUpdatePolicy(policy: RemoteRegistry['update_policy'], t: (key: string) => string) {
  switch (policy) {
    case 'full':
      return t('Full refresh');
    case 'incremental':
      return t('Incremental');
    case 'newer_only':
      return t('Newer only');
    default:
      return t('Not configured');
  }
}

function formatAuthType(authType: RemoteRegistry['auth_type'], t: (key: string) => string) {
  switch (authType) {
    case 'token':
      return t('Token');
    case 'basic':
      return t('Basic');
    default:
      return t('Not configured');
  }
}

function ChipListDetail({ values }: Readonly<{ values?: string[] }>) {
  const { t } = useTranslation();

  if (!values?.length) {
    return <TextCell text={t('None')} />;
  }

  return (
    <LabelGroup numLabels={8}>
      {values.map((value) => (
        <Label key={value}>{value}</Label>
      ))}
    </LabelGroup>
  );
}

export function RemoteRegistryDetails() {
  const { t } = useTranslation();
  const params = useParams<{ id: string }>();
  const isPrototype = isRegistriesPrototypeMode();

  useRegisterPrototypeNotes({
    id: 'hub-registries-details',
    title: t('Details'),
    content: isPrototype ? <RegistriesDetailsPrototypeNote /> : null,
  });

  const {
    data: remoteRegistryData,
    error: errorRemoteRegistry,
    refresh: refreshRemoteRegistry,
  } = useGet<HubItemsResponse<RemoteRegistry>>(
    hubAPI`/_ui/v1/execution-environments/registries/?name=${params.id}`
  );

  if (errorRemoteRegistry) {
    return <HubError error={errorRemoteRegistry} handleRefresh={refreshRemoteRegistry} />;
  }
  if (!remoteRegistryData) {
    return <LoadingPage breadcrumbs tabs />;
  }
  const remoteRegistry = remoteRegistryData?.data?.[0];

  const connectionStatus =
    remoteRegistry?.connection_status === 'connected'
      ? 'successful'
      : remoteRegistry?.connection_status === 'failed'
        ? 'failed'
        : 'unknown';

  return (
    <PageDetails>
      <PageDetail label={t('Name')}>{remoteRegistry?.name}</PageDetail>
      <PageDetail label={t('URL')}>
        <CopyCell text={remoteRegistry?.url ?? ''} />
      </PageDetail>
      {isPrototype ? (
        <PageDetail label={t('Connection status')}>
          <StatusCell status={connectionStatus} />
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Image count')}>{remoteRegistry?.image_count ?? 0}</PageDetail>
      ) : null}
      <PageDetail label={t('Sync status')}>
        {remoteRegistry?.last_sync_task &&
        Object.keys(remoteRegistry.last_sync_task).length > 0 &&
        remoteRegistry.last_sync_task.state ? (
          <StatusCell status={remoteRegistry.last_sync_task.state} />
        ) : (
          <TextCell text={t('Never synced')} />
        )}
      </PageDetail>
      {remoteRegistry?.last_sync_task?.finished_at ? (
        <PageDetail label={t('Last sync')}>
          <DateTimeCell value={remoteRegistry.last_sync_task.finished_at} />
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Sync schedule')}>
          {formatSyncSchedule(remoteRegistry?.sync_schedule, t)}
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Update policy')}>
          {formatUpdatePolicy(remoteRegistry?.update_policy, t)}
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Authentication type')}>
          {formatAuthType(remoteRegistry?.auth_type, t)}
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Tags to include')}>
          <ChipListDetail values={remoteRegistry?.include_tags} />
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Tags to exclude')}>
          <ChipListDetail values={remoteRegistry?.exclude_tags} />
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Architectures to sync')}>
          <ChipListDetail values={remoteRegistry?.include_architectures} />
        </PageDetail>
      ) : null}
      {isPrototype ? (
        <PageDetail label={t('Signature verification')}>
          {remoteRegistry?.signature_verification_enabled
            ? t('Require signed images')
            : t('Disabled')}
        </PageDetail>
      ) : null}
      {remoteRegistry?.proxy_url ? (
        <PageDetail label={t('Proxy URL')}>
          <CopyCell text={remoteRegistry.proxy_url} />
        </PageDetail>
      ) : null}
      <PageDetail label={t('TLS validation')}>
        {remoteRegistry?.tls_validation ? t('Enabled') : t('Disabled')}
      </PageDetail>
      <PageDetail label={t('Client certificate')}>
        {remoteRegistry?.client_cert ?? t('None')}
      </PageDetail>
      <PageDetail label={t('CA certificate')}>{remoteRegistry?.ca_cert ?? t('None')}</PageDetail>
      <PageDetail label={t('Download concurrency')}>
        {remoteRegistry?.download_concurrency?.toString() ?? t('None')}
      </PageDetail>
      <PageDetail label={t('Rate limit')}>{remoteRegistry?.rate_limit ?? t('None')}</PageDetail>
    </PageDetails>
  );
}
