import { DateTimeCell, ITableColumn, TextCell } from '@ansible/ansible-ui-framework';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { RegistryImageSignatureStatus } from '../../components/RegistryImageSignatureStatus';
import { RegistryImage } from '../../RegistryImage';

export function useRegistryImagesColumns() {
  const { t } = useTranslation();

  return useMemo<ITableColumn<RegistryImage>[]>(
    () => [
      {
        header: t('Name'),
        cell: (image) => <TextCell text={image.name} />,
        sort: 'name',
        defaultSort: true,
        card: 'name',
        list: 'name',
      },
      {
        header: t('Tags'),
        cell: (image) => <TextCell text={image.tags.join(', ')} />,
        list: 'secondary',
      },
      {
        header: t('Signature status'),
        cell: (image) => <RegistryImageSignatureStatus status={image.signature_status} />,
        sort: 'signature_status',
      },
      {
        header: t('Architecture'),
        cell: (image) => <TextCell text={image.architecture ?? t('Not specified')} />,
        sort: 'architecture',
      },
      {
        header: t('Last updated'),
        cell: (image) => <DateTimeCell value={image.last_updated} />,
        sort: 'last_updated',
      },
    ],
    [t]
  );
}
