import {
  ITableColumn,
  PageSelectOption,
  QueryParams,
  usePageDialog,
} from '@ansible/ansible-ui-framework';
import { SingleSelectDialog } from '@ansible/ansible-ui-framework/PageDialogs/SingleSelectDialog';
import { PageFormAsyncSingleSelect } from '@ansible/ansible-ui-framework/PageForm/Inputs/PageFormAsyncSingleSelect';
import { useID } from '@ansible/ansible-ui-framework/hooks/useID';
import { requestGet } from '@ansible/common-ui/crud/Data';
import { useCallback, useEffect, useMemo, useRef } from 'react';
import {
  FieldPath,
  FieldValues,
  PathValue,
  useFormContext,
  useWatch,
} from 'react-hook-form';
import { useTranslation } from 'react-i18next';
import { RegistryImage } from '../../administration/remote-registries/RegistryImage';
import { hubAPI } from '../../common/api/formatPath';
import { HubItemsResponse, useHubView } from '../../common/useHubView';

type RegistryRef = {
  id: string;
  name: string;
};

export function suggestExecutionEnvironmentName(imageName: string) {
  const segments = imageName.split('/');
  const base = segments[segments.length - 1] ?? imageName;
  return base.replace(/[^0-9A-Za-z._-]/g, '-');
}

export function PageFormRegistryImageSelect<
  TFieldValues extends FieldValues & {
    registry?: RegistryRef;
    upstream_name?: string;
    name?: string;
  },
  TFieldName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>(props: Readonly<{
  name: TFieldName;
  onImageSelected?: (image: RegistryImage) => void;
  tableColumns: ITableColumn<RegistryImage>[];
}>) {
  const { t } = useTranslation();
  const id = useID(props);
  const { setValue, getValues } = useFormContext<TFieldValues>();
  const registry = useWatch<TFieldValues>({
    name: 'registry' as FieldPath<TFieldValues>,
  }) as RegistryRef | undefined;
  const previousRegistryId = useRef<string | undefined>();
  const [_, setDialog] = usePageDialog();

  useEffect(() => {
    const registryId = registry?.id;
    if (previousRegistryId.current && previousRegistryId.current !== registryId) {
      setValue(props.name, '' as PathValue<TFieldValues, TFieldName>);
    }
    previousRegistryId.current = registryId;
  }, [registry?.id, props.name, setValue]);

  const handleImageSelected = useCallback(
    (image: RegistryImage) => {
      setValue(props.name, image.name as PathValue<TFieldValues, TFieldName>);
      const currentName = getValues('name' as FieldPath<TFieldValues>);
      if (typeof currentName !== 'string' || !currentName.trim()) {
        setValue(
          'name' as FieldPath<TFieldValues>,
          suggestExecutionEnvironmentName(image.name) as PathValue<TFieldValues, FieldPath<TFieldValues>>
        );
      }
      props.onImageSelected?.(image);
    },
    [getValues, props, setValue]
  );

  const queryOptions = useCallback(
    async (options: { search?: string; next?: string | number; signal?: AbortSignal }) => {
      if (!registry?.id) {
        return { remaining: 0, options: [], next: 0 };
      }
      try {
        const response = await requestGet<HubItemsResponse<RegistryImage>>(
          hubAPI`/_ui/v1/execution-environments/registries/${registry.id}/images/`,
          options.signal
        );
        let images = response.data ?? [];
        if (options.search) {
          const search = options.search.toLowerCase();
          images = images.filter((image) => image.name.toLowerCase().includes(search));
        }
        return {
          remaining: 0,
          options: images.map(
            (image) =>
              ({
                label: image.name,
                value: image.name,
              }) as PageSelectOption<PathValue<TFieldValues, TFieldName>>
          ),
          next: 0,
        };
      } catch {
        return { remaining: 0, options: [], next: 0 };
      }
    },
    [registry?.id]
  );

  const openBrowse = useCallback(() => {
    if (!registry?.id) {
      return;
    }
    const currentValue = getValues(props.name);
    setDialog(
      <SelectRegistryImage
        registryId={registry.id}
        title={t('Image')}
        tableColumns={props.tableColumns}
        onSelect={handleImageSelected}
        defaultSelection={
          typeof currentValue === 'string' && currentValue
            ? [{ id: currentValue, name: currentValue, tags: [], signature_status: 'unsigned', last_updated: '' }]
            : []
        }
      />
    );
  }, [getValues, handleImageSelected, props.name, props.tableColumns, registry?.id, setDialog, t]);

  if (!registry?.id) {
    return (
      <PageFormAsyncSingleSelect<TFieldValues, TFieldName>
        id={id}
        name={props.name}
        label={t('Image')}
        labelHelp={t('Select a registry before choosing an image from its catalog.')}
        queryOptions={async () => ({ remaining: 0, options: [], next: 0 })}
        placeholder={t('Select a registry first')}
        queryPlaceholder={t('Loading images...')}
        queryErrorText={t('Error loading images')}
        isRequired
        isDisabled={t('Select a registry first')}
        queryLabel={(value) => String(value)}
      />
    );
  }

  return (
    <PageFormAsyncSingleSelect<TFieldValues, TFieldName>
      id={id}
      name={props.name}
      label={t('Image')}
      labelHelp={t('Image path within the selected registry.')}
      queryOptions={queryOptions}
      placeholder={t('Select image')}
      queryPlaceholder={t('Loading images...')}
      queryErrorText={t('Error loading images')}
      isRequired
      onBrowse={openBrowse}
      queryLabel={(value) => String(value)}
    />
  );
}

function SelectRegistryImage(
  props: Readonly<{
    registryId: string;
    title: string;
    onSelect: (image: RegistryImage) => void;
    defaultSelection?: RegistryImage[];
    tableColumns: ITableColumn<RegistryImage>[];
  }>
) {
  const imagesUrl = hubAPI`/_ui/v1/execution-environments/registries/${props.registryId}/images/`;
  const queryParams = useMemo<QueryParams>(() => ({}), []);

  const view = useHubView<RegistryImage>({
    url: imagesUrl,
    tableColumns: props.tableColumns,
    keyFn: (image) => image.id,
    disableQueryString: true,
    defaultSelection: props.defaultSelection,
    queryParams,
  });

  return (
    <SingleSelectDialog<RegistryImage>
      title={props.title}
      onSelect={props.onSelect}
      toolbarFilters={[]}
      tableColumns={props.tableColumns}
      view={view}
    />
  );
}
