import { createContext, ReactNode, useContext, useEffect, useRef, useState } from 'react';

interface PrototypeNotesEntry {
  id: string;
  title: string;
  content: ReactNode;
}

interface PrototypeNotesContextValue {
  activeEntry: PrototypeNotesEntry | null;
  registerEntry: (entry: PrototypeNotesEntry) => void;
  unregisterEntry: (id: string) => void;
}

const PrototypeNotesContext = createContext<PrototypeNotesContextValue>({
  activeEntry: null,
  registerEntry: () => undefined,
  unregisterEntry: () => undefined,
});

export function PrototypeNotesRegistryProvider({ children }: Readonly<{ children: ReactNode }>) {
  const [activeEntry, setActiveEntry] = useState<PrototypeNotesEntry | null>(null);

  const registerEntry = (entry: PrototypeNotesEntry) => {
    setActiveEntry(entry);
  };

  const unregisterEntry = (id: string) => {
    setActiveEntry((prev) => (prev?.id === id ? null : prev));
  };

  return (
    <PrototypeNotesContext.Provider value={{ activeEntry, registerEntry, unregisterEntry }}>
      {children}
    </PrototypeNotesContext.Provider>
  );
}

export function usePrototypeNotesRegistry() {
  return useContext(PrototypeNotesContext);
}

export function useRegisterPrototypeNotes(entry: PrototypeNotesEntry) {
  const { registerEntry, unregisterEntry } = useContext(PrototypeNotesContext);
  const entryRef = useRef(entry);
  entryRef.current = entry;

  useEffect(() => {
    registerEntry(entryRef.current);
    return () => {
      unregisterEntry(entryRef.current.id);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entry.id]);
}
