import { DateTimeCell, ITableColumn, TextCell } from '@ansible/ansible-ui-framework';
import { StatusCell } from '@ansible/common-ui/Status';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';

interface RegistrySyncHistoryEntry {
  id: string;
  started_at: string;
  finished_at: string | null;
  state: 'completed' | 'running' | 'failed' | 'pending';
  items_synced: number;
  items_failed: number;
  update_policy: 'full' | 'incremental' | 'newer_only';
}

export type { RegistrySyncHistoryEntry };

export function useRegistrySyncHistoryColumns() {
  const { t } = useTranslation();

  return useMemo<ITableColumn<RegistrySyncHistoryEntry>[]>(
    () => [
      {
        header: t('Started'),
        cell: (entry) => <DateTimeCell value={entry.started_at} />,
        sort: 'started_at',
        defaultSort: true,
        defaultSortDirection: 'desc',
      },
      {
        header: t('Finished'),
        cell: (entry) => <DateTimeCell value={entry.finished_at ?? undefined} />,
        sort: 'finished_at',
      },
      {
        header: t('Status'),
        cell: (entry) => <StatusCell status={entry.state} />,
        sort: 'state',
      },
      {
        header: t('Items synced'),
        cell: (entry) => <TextCell text={String(entry.items_synced)} />,
        sort: 'items_synced',
      },
      {
        header: t('Items failed'),
        cell: (entry) => <TextCell text={String(entry.items_failed)} />,
        sort: 'items_failed',
      },
      {
        header: t('Update policy'),
        cell: (entry) => <TextCell text={entry.update_policy.replace('_', ' ')} />,
      },
    ],
    [t]
  );
}
