import { LoadingPage } from '@ansible/ansible-ui-framework';
import { ResourceUserAccess } from '@ansible/common-ui/access/components/ResourceUserAccess';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useOutletContext, useParams } from 'react-router-dom';
import { hubAPI } from '../../../common/api/formatPath';
import { parsePulpIDFromURL } from '../../../common/api/hub-api-utils';
import { HubError } from '../../../common/HubError';
import { HubItemsResponse } from '../../../common/useHubView';
import { HubRoute } from '../../../main/HubRoutes';
import { RemoteRegistry } from '../RemoteRegistry';

export function RemoteRegistryUserAccess() {
  const params = useParams<{ id: string }>();
  const { remoteRegistry: contextRegistry } = useOutletContext<{ remoteRegistry?: RemoteRegistry }>();

  const registryName = params.id ?? contextRegistry?.name;
  const { data, error, refresh } = useGet<HubItemsResponse<RemoteRegistry>>(
    registryName ? hubAPI`/_ui/v1/execution-environments/registries/?name=${registryName}` : undefined
  );

  const remoteRegistry = contextRegistry ?? data?.data?.[0];

  if (!remoteRegistry && !error) {
    return <LoadingPage />;
  }

  if (error) {
    return <HubError error={error} handleRefresh={refresh} />;
  }

  return (
    <ResourceUserAccess
      service="hub"
      id={parsePulpIDFromURL(remoteRegistry?.pulp_href) || remoteRegistry?.id || ''}
      name={remoteRegistry?.name || ''}
      type={'galaxy.containerregistry'}
      addRolesRoute={HubRoute.RemoteRegistryAddUsers}
      manageRoleRoute={HubRoute.RemoteRegistryManageUsers}
    />
  );
}
