import { PageFormSwitch, usePageAlertToaster, usePageDialog } from '@ansible/ansible-ui-framework';
import { createRequestError } from '@ansible/common-ui/crud/RequestError';
import { getCookie } from '@ansible/common-ui/crud/cookie';
import { downloadBlobFile } from '@ansible/ansible-ui-framework/utils/download-file';
import { Modal, ModalBody, ModalHeader, ModalVariant } from '@patternfly/react-core';
import { useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { HubPageForm } from '../../../common/HubPageForm';
import { hubAPI } from '../../../common/api/formatPath';
import { extractErrorDescription } from '../../../common/utils/errorUtils';
import { RemoteRegistry } from '../RemoteRegistry';

interface ExportBundleFormValues {
  include_signatures: boolean;
}

async function postExportBundle(registry: RemoteRegistry, values: ExportBundleFormValues) {
  const response = await fetch(
    hubAPI`/_ui/v1/execution-environments/registries/${registry.id}/export-bundle/`,
    {
      method: 'POST',
      body: JSON.stringify({ include_signatures: values.include_signatures }),
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRFToken': getCookie('csrftoken') ?? '',
      },
    }
  );

  if (!response.ok) {
    throw await createRequestError(response);
  }

  const blob = await response.blob();
  downloadBlobFile(`${registry.name}-bundle`, 'tar', blob);
}

export function useExportRegistryBundle() {
  const { t } = useTranslation();
  const [_, setDialog] = usePageDialog();
  const alertToaster = usePageAlertToaster();
  const onClose = useCallback(() => setDialog(undefined), [setDialog]);

  const defaultValues = useMemo<ExportBundleFormValues>(
    () => ({
      include_signatures: true,
    }),
    []
  );

  return useCallback(
    (registry: RemoteRegistry) => {
      setDialog(
        <Modal
          aria-label={t('Export bundle')}
          isOpen
          onClose={onClose}
          variant={ModalVariant.medium}
          tabIndex={0}
        >
          <ModalHeader
            title={t('Export bundle')}
            description={t(
              'Create an offline content bundle from this registry for transfer to a disconnected Hub. Signatures and metadata are included per ANSTRAT-1758 M4.'
            )}
          />
          <ModalBody style={{ paddingLeft: 0 }}>
            <HubPageForm<ExportBundleFormValues>
              submitText={t('Export')}
              onCancel={onClose}
              defaultValue={defaultValues}
              singleColumn
              disablePadding
              disableSubmitOnEnter
              onSubmit={(values) =>
                postExportBundle(registry, values)
                  .then(() => {
                    alertToaster.addAlert({
                      variant: 'success',
                      title: t('Bundle export complete'),
                      children: t('The offline bundle download has started.'),
                    });
                    onClose();
                  })
                  .catch((error: unknown) => {
                    alertToaster.addAlert({
                      variant: 'danger',
                      title: t('Failed to export bundle'),
                      children: extractErrorDescription(error),
                    });
                  })
              }
            >
              <PageFormSwitch<ExportBundleFormValues>
                name="include_signatures"
                label={t('Include signatures')}
                labelHelp={t('Include image signatures and signing metadata in the export bundle.')}
                labelOn={t('Include signatures in bundle')}
              />
            </HubPageForm>
          </ModalBody>
        </Modal>
      );
    },
    [alertToaster, defaultValues, onClose, setDialog, t]
  );
}
