import { IPageAction, PageActionSelection, PageActionType } from '@ansible/ansible-ui-framework';
import { ButtonVariant } from '@patternfly/react-core';
import { ThumbsDownIcon, ThumbsUpIcon } from '@patternfly/react-icons';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { EeApproval } from '../EeApproval';
import { useApproveEeApprovals } from './useApproveEeApprovals';
import { useRejectEeApprovals } from './useRejectEeApprovals';

export function useEeApprovalActions(callback: (items: EeApproval[]) => void) {
  const { t } = useTranslation();
  const approveEeApprovals = useApproveEeApprovals(callback);
  const rejectEeApprovals = useRejectEeApprovals(callback);

  return useMemo<IPageAction<EeApproval>[]>(
    () => [
      { type: PageActionType.Seperator },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Single,
        isPinned: true,
        icon: ThumbsUpIcon,
        label: t('Approve image'),
        onClick: (approval) => approveEeApprovals([approval]),
        isDisabled: (approval) =>
          approval.status === 'approved' ? t('Image is already approved') : undefined,
      },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Single,
        isPinned: true,
        icon: ThumbsDownIcon,
        label: t('Reject image'),
        variant: ButtonVariant.danger,
        onClick: (approval) => rejectEeApprovals([approval]),
        isDisabled: (approval) =>
          approval.status === 'rejected' ? t('Image is already rejected') : undefined,
      },
    ],
    [approveEeApprovals, rejectEeApprovals, t]
  );
}

export function useEeApprovalsToolbarActions(callback: (items: EeApproval[]) => void) {
  const { t } = useTranslation();
  const approveEeApprovals = useApproveEeApprovals(callback);
  const rejectEeApprovals = useRejectEeApprovals(callback);

  return useMemo<IPageAction<EeApproval>[]>(
    () => [
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: ThumbsUpIcon,
        label: t('Approve images'),
        onClick: approveEeApprovals,
      },
      { type: PageActionType.Seperator },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: ThumbsDownIcon,
        label: t('Reject images'),
        onClick: rejectEeApprovals,
        isDanger: true,
      },
    ],
    [approveEeApprovals, rejectEeApprovals, t]
  );
}
