import {
  PageTable,
  useGetPageUrl,
  PageLayoutWithUnauthorized,
} from '@ansible/ansible-ui-framework';
import { PageTableEmptyState } from '@ansible/ansible-ui-framework/PageTable/PageTableEmptyState';
import { ButtonLink } from '@ansible/ansible-ui-framework/components/ButtonLink';
import { useGetDocsUrl } from '@ansible/common-ui/utils/useGetDocsUrl';
import { ButtonVariant } from '@patternfly/react-core';
import { PlusCircleIcon } from '@patternfly/react-icons';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useRegisterPrototypeNotes } from '../../../../platform/common/PrototypeNotesRegistry';
import { filterInsightsBulkActions } from '../../common/isInsights';
import { hubAPI } from '../../common/api/formatPath';
import { pulpHrefKeyFn } from '../../common/api/hub-api-utils';
import { useHubConfig } from '../../common/useHubConfig';
import { useHubView } from '../../common/useHubView';
import { isAccessDeniedError } from '../../common/utils/errorUtils';
import { HubRoute } from '../../main/HubRoutes';
import { RegistriesListPrototypeNote } from '../../../../platform/src/prototype/registries/RegistriesListPrototypeNotes';
import { RemoteRegistry } from './RemoteRegistry';
import { getRegistriesLabel, getRegistryLabel, isRegistriesPrototypeMode } from './registriesLabels';
import { useRemoteRegistriesColumns } from './hooks/useRemoteRegistriesColumns';
import { useRemoteRegistriesToolbarActions } from './hooks/useRemoteRegistriesToolbarActions';
import { useRemoteRegistryActions } from './hooks/useRemoteRegistryActions';
import { useRemoteRegistryFilters } from './hooks/useRemoteRegistryFilters';

export function RemoteRegistries() {
  const { t } = useTranslation();
  const toolbarFilters = useRemoteRegistryFilters();
  const tableColumns = useRemoteRegistriesColumns();
  const config = useHubConfig();
  const docsUrl = useGetDocsUrl(config, 'remoteRegistries');
  const getPageUrl = useGetPageUrl();
  const isPrototype = isRegistriesPrototypeMode();

  const registriesLabel = getRegistriesLabel(t);
  const registryLabel = getRegistryLabel(t);

  useRegisterPrototypeNotes({
    id: 'hub-registries-list',
    title: isPrototype ? registriesLabel : t('Remote Registries'),
    content: isPrototype ? <RegistriesListPrototypeNote /> : null,
  });

  const view = useHubView<RemoteRegistry>({
    url: hubAPI`/_ui/v1/execution-environments/registries/`,
    keyFn: pulpHrefKeyFn,
    toolbarFilters,
    tableColumns,
  });

  const allToolbarActions = useRemoteRegistriesToolbarActions(view);
  const toolbarActions = useMemo(
    () => filterInsightsBulkActions(allToolbarActions),
    [allToolbarActions]
  );
  const rowActions = useRemoteRegistryActions({
    onRemoteRegistryDeleted: view.unselectItemsAndRefresh,
    refresh: view.refresh,
  });

  const isUnauthorized = isAccessDeniedError(view.error);

  const description = isPrototype
    ? t(
        'Connect to OCI-compliant registries to browse and manage execution environment images directly from external sources.'
      )
    : t(
        'Remote registries provide a central location for users to search, retrieve, and install Ansible content.'
      );

  return (
    <PageLayoutWithUnauthorized
      isUnauthorized={isUnauthorized}
      resourceName={registriesLabel}
      title={registriesLabel}
      titleHelpTitle={registriesLabel}
      titleHelp={description}
      description={description}
      titleDocLink={docsUrl}
    >
      <PageTable<RemoteRegistry>
        id="hub-remote-registries-table"
        defaultSubtitle={registryLabel}
        emptyState={
          <PageTableEmptyState
            title={isPrototype ? t('No registries yet') : t('No remote registries yet')}
            description={
              isPrototype
                ? t('Connect a registry to browse execution environment images from an external source.')
                : t(
                    'You can create a remote registry to manage configurations for remote execution environments.'
                  )
            }
          >
            <ButtonLink
              icon={<PlusCircleIcon />}
              variant={ButtonVariant.primary}
              href={getPageUrl(HubRoute.CreateRemoteRegistry)}
              data-cy="create-remote-registry"
              data-testid="create-remote-registry"
            >
              {isPrototype ? t('Create registry') : t('Create registry')}
            </ButtonLink>
          </PageTableEmptyState>
        }
        errorStateTitle={
          isPrototype ? t('Error loading registries') : t('Error loading remote registries')
        }
        rowActions={rowActions}
        tableColumns={tableColumns}
        toolbarActions={toolbarActions}
        toolbarFilters={toolbarFilters}
        {...view}
      />
    </PageLayoutWithUnauthorized>
  );
}
