export function isRegistriesPrototypeMode() {
  return import.meta.env.VITE_DEMO_MODE === 'true';
}

export function getRegistriesLabel(t: (key: string) => string) {
  return isRegistriesPrototypeMode() ? t('Registries') : t('Remote Registries');
}

export function getRegistryLabel(t: (key: string) => string) {
  return isRegistriesPrototypeMode() ? t('Registry') : t('Remote Registry');
}
