import { PrototypeNote } from '../../../common/PrototypeNote';

export function RegistrySyncHistoryPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>
          This tab logs <strong>batch sync jobs</strong> for this registry: status, items
          synced/failed, and update policy. Operational history only — not governance audit (approve,
          sign, config changes).
        </>,
        <>
          <strong>Sep&nbsp;3:</strong> Team debated whether periodic sync is needed at all if Hub
          pulls live from remote on every request. Counter-argument: the UI still needs scheduled
          refresh to discover new tags/versions and to support governance on a local copy. This tab
          stays valid under either model.
        </>,
        <>
          Rows with failures should offer <strong>View failures</strong> (modal with per-image
          errors) and an optional link to Hub Task detail for full logs — same pattern as Collection
          Repository sync &rarr; task management.
        </>,
      ]}
      questions={[
        'Should sync failures support "Retry failed items" only, or always re-run the full sync job?',
      ]}
    />
  );
}
