import { PrototypeNote } from '../../../common/PrototypeNote';

export function RegistryImagesPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>
          This tab is the <strong>full registry catalog</strong> — browse all discoverable images and
          tags from the connected registry.
        </>,
        <>
          <strong>Signature status</strong> here is <strong>read-only</strong> (Signed / Unsigned /
          Unverified). <strong>Sign execution environment</strong> stays on the EE list and EE
          detail kebab — signing is a governance step on the EE definition, not while browsing.
        </>,
        <>
          <strong>UX recommendation (SDP Q21):</strong> When signature verification fails, show the
          image with an explicit <strong>Unverified</strong> or <strong>Verification failed</strong>{' '}
          label rather than hiding it from the list. Hiding causes &ldquo;I know this image exists
          upstream&rdquo; support confusion.
        </>,
        <>
          <strong>Create execution environment</strong> row action pre-fills the EE form from the
          selected image. Image picker on the create form may hide unsupported architectures; this
          tab shows the full catalog for browsing.
        </>,
      ]}
      questions={[
        'Should unsupported architectures be hidden from this catalog, or only from the Create EE picker?',
        'SDP Q21 (stakeholder): Confirm show-with-label vs hide-from-list for signature mismatch.',
      ]}
    />
  );
}
