import { PrototypeNote } from '../../../common/PrototypeNote';

export function RegistriesListPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>
          <strong>Air-gapped transfer (M4):</strong> <strong>Import bundle</strong> on this list;
          <strong> Export bundle</strong> on each registry&apos;s detail kebab. Together they support
          offline transfer between connected and disconnected Hubs.
        </>,
        <>
          <strong>Import bundle:</strong> Upload the offline <code>.tar</code> package only — the
          bundle carries registry metadata, images, and signatures. <strong>Target registry</strong>{' '}
          chooses whether to create a new registry connection from bundle metadata (
          <strong>Create registry from bundle</strong>) or load content into an existing registry on
          this Hub. <strong>Verify signatures</strong> is an optional integrity check before import
          (common in regulated air-gap flows).
        </>,
        <>
          <strong>Sep&nbsp;3 pod sync:</strong> Team is re-evaluating whether Hub must keep a{' '}
          <strong>local image copy</strong> (via Pulp or a bundled storage service) for signing,
          approvals, and Controller jobs — vs. a lighter &ldquo;catalog only&rdquo; model. Open until
          after Home Days.
        </>,
      ]}
      questions={[
        'When Collections support arrives (ANSTRAT-1705), should we add a parallel "Collection sources" pattern?',
        'Should clicking Sync registry open a modal to override update policy or sync scope for this run only (like Collection Repositories: Mirror / Optimize)?',
        'Do we need a single cross-registry image catalog, or is Registries → Images per registry enough?',
      ]}
    />
  );
}
