import { PrototypeNote } from '../../../common/PrototypeNote';

export function RegistriesFormPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>
          New fields (sync schedule, update policy, signature verification, TLS validation) are
          prototype assumptions pending backend API shape from ANSTRAT-1758.
        </>,
        <>
          <strong>Sync scope (SDP Q17/Q18):</strong> Include/exclude tags and architectures to sync
          limit disk use. Uses the same tag chip pattern as the EE create form. Empty = sync all.
        </>,
        <>
          <strong>Local copy vs. catalog only (Sep&nbsp;3):</strong> Early ANSTRAT discussion
          included <strong>metadata-only sync</strong> — Hub records image names/tags from the
          external registry without downloading image layers. Today&apos;s Pulp model is the
          opposite: Hub stores a <strong>full local copy</strong> on disk. The Sep&nbsp;3 sync
          leaned back toward needing a local copy for signing, approvals, and supply-chain checks
          before Controller runs jobs. Sync fields on this form assume periodic refresh either way;
          what gets copied is TBD.
        </>,
        <>
          Registry sync on creation stays a <strong>manual, deliberate action</strong> (matching
          Collections) — saving this form does not auto-sync.
        </>,
        <>
          <strong>Signature verification</strong> (registry form): When enabled, Hub rejects or
          blocks <strong>unsigned or failed-verification images from this registry</strong> during
          sync and when users reference them in EEs — not a per-EE toggle. Org-wide enforcement is
          a separate SDP question (out of prototype scope).
        </>,
      ]}
      questions={[
        'If Hub keeps a local copy, should sync pull full image layers, metadata only, or both depending on update policy?',
        'Should Hub support webhook-based sync in addition to scheduled polling, or is polling sufficient for Phase 1?',
      ]}
    />
  );
}
