import {
  IPageAction,
  PageActionSelection,
  PageActionType,
  usePageNavigate,
} from '@ansible/ansible-ui-framework';
import { ButtonVariant } from '@patternfly/react-core';
import { ImportIcon, PlusCircleIcon, TrashIcon } from '@patternfly/react-icons';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { IHubView } from '../../../common/useHubView';
import { HubRoute } from '../../../main/HubRoutes';
import { RemoteRegistry } from '../RemoteRegistry';
import { isRegistriesPrototypeMode } from '../registriesLabels';
import { useDeleteRemoteRegistries } from './useDeleteRemoteRegistries';
import { useImportRegistryBundle } from './useImportRegistryBundle';

export function useRemoteRegistriesToolbarActions(view: IHubView<RemoteRegistry>) {
  const { t } = useTranslation();
  const deleteRemoteRegistries = useDeleteRemoteRegistries(view.unselectItemsAndRefresh);
  const pageNavigate = usePageNavigate();
  const isPrototype = isRegistriesPrototypeMode();
  const importRegistryBundle = useImportRegistryBundle(view.pageItems ?? []);

  const actions = useMemo<IPageAction<RemoteRegistry>[]>(
    () => [
      {
        icon: PlusCircleIcon,
        isPinned: true,
        label: t('Create registry'),
        onClick: () => pageNavigate(HubRoute.CreateRemoteRegistry),
        selection: PageActionSelection.None,
        type: PageActionType.Button,
        variant: ButtonVariant.primary,
      },
      ...(isPrototype
        ? [
            {
              icon: ImportIcon,
              isPinned: true,
              label: t('Import bundle'),
              onClick: () => importRegistryBundle(),
              selection: PageActionSelection.None,
              type: PageActionType.Button,
              variant: ButtonVariant.secondary,
            } as IPageAction<RemoteRegistry>,
          ]
        : []),
      { type: PageActionType.Seperator },
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Multiple,
        icon: TrashIcon,
        label: t('Delete registries'),
        onClick: deleteRemoteRegistries,
        isDanger: true,
      },
    ],
    [t, pageNavigate, deleteRemoteRegistries, isPrototype, importRegistryBundle]
  );

  return actions;
}
