import { ReactNode } from 'react';

interface PrototypeNoteProps {
  notes?: ReactNode[];
  questions?: ReactNode[];
  defaultOpen?: boolean;
}

export function PrototypeNote({ notes = [], questions = [] }: Readonly<PrototypeNoteProps>) {
  return (
    <div style={{ fontSize: '13px', lineHeight: 1.5, color: '#1b1d21' }}>
      {notes.length > 0 && (
        <ul style={{ margin: '0 0 8px', paddingLeft: '18px', listStyleType: 'disc' }}>
          {notes.map((note, i) => (
            <li key={i} style={{ marginBottom: '4px', display: 'list-item' }}>
              {note}
            </li>
          ))}
        </ul>
      )}
      {questions.length > 0 && (
        <>
          <div
            style={{
              fontWeight: 700,
              fontSize: '11px',
              letterSpacing: '0.06em',
              textTransform: 'uppercase',
              color: '#f57f17',
              marginBottom: '6px',
              marginTop: notes.length > 0 ? '12px' : 0,
            }}
          >
            Open Questions
          </div>
          <ul style={{ margin: 0, paddingLeft: '18px', listStyleType: 'disc' }}>
            {questions.map((q, i) => (
              <li key={i} style={{ marginBottom: '4px', display: 'list-item' }}>
                {q}
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}
