import { PFColorE, TextCell } from '@ansible/ansible-ui-framework';
import {
  CheckCircleIcon,
  ExclamationCircleIcon,
  ExclamationTriangleIcon,
  QuestionCircleIcon,
} from '@patternfly/react-icons';
import { useTranslation } from 'react-i18next';
import { RegistryImage } from '../RegistryImage';

export function RegistryImageSignatureStatus({
  status,
}: Readonly<{ status: RegistryImage['signature_status'] }>) {
  const { t } = useTranslation();

  switch (status) {
    case 'signed':
      return (
        <TextCell text={t('Signed')} color={PFColorE.Success} icon={<CheckCircleIcon />} />
      );
    case 'unsigned':
      return (
        <TextCell text={t('Unsigned')} color={PFColorE.Warning} icon={<ExclamationTriangleIcon />} />
      );
    case 'failed':
      return (
        <TextCell
          text={t('Verification failed')}
          color={PFColorE.Danger}
          icon={<ExclamationCircleIcon />}
        />
      );
    case 'unverified':
      return (
        <TextCell text={t('Unverified')} color={PFColorE.Default} icon={<QuestionCircleIcon />} />
      );
    default:
      return null;
  }
}
