import { postRequest } from '@ansible/common-ui/crud/Data';
import {
  Alert,
  Button,
  Modal,
  ModalBody,
  ModalFooter,
  ModalHeader,
  ModalVariant,
  Spinner,
} from '@patternfly/react-core';
import { type MouseEvent, useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { useTranslation } from 'react-i18next';
import { hubAPI } from '../../common/api/formatPath';
import { RemoteRegistry } from './RemoteRegistry';

interface RemoteRegistryFormValues extends RemoteRegistry {
  client_key?: string | null;
  password?: string | null;
  proxy_password?: string | null;
  proxy_username?: string | null;
  username?: string | null;
  token?: string | null;
}

interface TestResult {
  variant: 'success' | 'danger';
  message: string;
}

export function RegistryConnectionTestButton({
  registryId,
}: Readonly<{ registryId?: string }>) {
  const { t } = useTranslation();
  const { getValues, watch } = useFormContext<RemoteRegistryFormValues>();
  const url = watch('url');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<TestResult | null>(null);

  const runTest = async () => {
    setIsTesting(true);
    setTestResult(null);
    const values = getValues();
    const testUrl = registryId
      ? hubAPI`/_ui/v1/execution-environments/registries/${registryId}/test-connection/`
      : hubAPI`/_ui/v1/execution-environments/registries/test-connection/`;

    try {
      const response = (await postRequest(testUrl, {
        url: values.url,
        auth_type: values.auth_type,
        username: values.username,
        password: values.password,
        token: values.token,
      })) as { success?: boolean; message?: string };

      if (response.success) {
        setTestResult({
          variant: 'success',
          message: response.message ?? t('Connection successful'),
        });
      } else {
        setTestResult({
          variant: 'danger',
          message: response.message ?? t('Connection failed'),
        });
      }
    } catch (error) {
      setTestResult({
        variant: 'danger',
        message:
          error instanceof Error ? error.message : t('Connection failed: invalid credentials'),
      });
    } finally {
      setIsTesting(false);
    }
  };

  const handleOpenTest = (event: MouseEvent) => {
    event.preventDefault();
    setIsModalOpen(true);
    void runTest();
  };

  const handleClose = () => {
    setIsModalOpen(false);
    setTestResult(null);
  };

  return (
    <>
      <Button
        variant="secondary"
        aria-label={t('Test connection')}
        onClick={handleOpenTest}
        isDisabled={!url?.trim()}
      >
        {t('Test connection')}
      </Button>
      <Modal
        variant={ModalVariant.small}
        isOpen={isModalOpen}
        onClose={handleClose}
        aria-label={t('Test connection')}
      >
        <ModalHeader title={t('Test connection')} />
        <ModalBody>
          {isTesting ? (
            <Spinner size="lg" aria-label={t('Testing connection')} />
          ) : testResult ? (
            <Alert
              variant={testResult.variant}
              title={
                testResult.variant === 'success'
                  ? t('Connection successful')
                  : t('Connection failed')
              }
              isInline
            >
              {testResult.message}
            </Alert>
          ) : null}
        </ModalBody>
        <ModalFooter>
          <Button key="close" variant="primary" onClick={handleClose}>
            {t('Close')}
          </Button>
        </ModalFooter>
      </Modal>
    </>
  );
}
