import { useTranslation } from 'react-i18next';
import { FormChipsInput } from './FormChipsInput';

export function TagsInputGroup(
  props: Readonly<{
    tags: string[];
    setTags: (tags: string[]) => void;
    mode: 'exclude' | 'include';
    fieldId?: string;
  }>
) {
  const { tags, setTags, mode, fieldId } = props;
  const { t } = useTranslation();

  const label =
    mode === 'exclude' ? t('Tags to exclude') : t('Tags to include');
  const help =
    mode === 'exclude'
      ? t('Image tag versions to skip during sync. Press Enter after each tag.')
      : t('Only sync images with these tags. Leave empty to sync all tags. Press Enter after each tag.');

  return (
    <FormChipsInput
      label={label}
      labelHelp={help}
      chips={tags}
      onChipsChange={setTags}
      fieldId={fieldId ?? `registry-tags-${mode}`}
    />
  );
}
