import GripVerticalIcon from '@patternfly/react-icons/dist/esm/icons/grip-vertical-icon';
import TimesIcon from '@patternfly/react-icons/dist/esm/icons/times-icon';
import { useCallback, useEffect, useRef, useState } from 'react';
import { usePrototypeNotesRegistry } from './PrototypeNotesRegistry';

export function PrototypeDesignNotesLauncher() {
  const { activeEntry } = usePrototypeNotesRegistry();
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const dragging = useRef(false);
  const dragStart = useRef({ mx: 0, my: 0, px: 0, py: 0 });

  // Close panel when active notes change (page navigation)
  useEffect(() => {
    setOpen(false);
    setPos({ x: 0, y: 0 });
  }, [activeEntry?.id]);

  const onGripMouseDown = useCallback(
    (e: React.MouseEvent) => {
      dragging.current = true;
      dragStart.current = { mx: e.clientX, my: e.clientY, px: pos.x, py: pos.y };
      e.preventDefault();
    },
    [pos]
  );

  useEffect(() => {
    const onMove = (e: MouseEvent) => {
      if (!dragging.current) return;
      setPos({
        x: dragStart.current.px + (e.clientX - dragStart.current.mx),
        y: dragStart.current.py + (e.clientY - dragStart.current.my),
      });
    };
    const onUp = () => {
      dragging.current = false;
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, []);

  if (!activeEntry) return null;

  return (
    <>
      {open && (
        <div
          style={{
            position: 'fixed',
            bottom: `calc(56px + ${-pos.y}px)`,
            left: `calc(16px + ${pos.x}px)`,
            width: '475px',
            maxHeight: '60vh',
            zIndex: 500,
            display: 'flex',
            flexDirection: 'column',
            border: '2px dashed #f9a825',
            borderRadius: '6px',
            backgroundColor: '#fffde7',
            boxShadow: '0 4px 16px rgba(0,0,0,0.18)',
            overflow: 'hidden',
          }}
        >
          {/* Draggable header */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              padding: '8px 12px',
              borderBottom: '1px dashed #f9a825',
              backgroundColor: '#fff8e1',
              cursor: 'grab',
              flexShrink: 0,
            }}
            onMouseDown={onGripMouseDown}
          >
            <GripVerticalIcon style={{ color: '#f57f17', flexShrink: 0 }} />
            <span
              style={{
                fontSize: '11px',
                fontWeight: 700,
                textTransform: 'uppercase',
                letterSpacing: '0.06em',
                color: '#f57f17',
              }}
            >
              Design Note
            </span>
            <span
              style={{
                fontSize: '13px',
                fontWeight: 600,
                color: '#1b1d21',
                flex: 1,
                marginLeft: '4px',
              }}
            >
              {activeEntry.title}
            </span>
            <button
              onClick={() => setOpen(false)}
              aria-label="Close design notes"
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                padding: '2px',
                color: '#6a6e73',
                display: 'flex',
                alignItems: 'center',
                flexShrink: 0,
              }}
            >
              <TimesIcon />
            </button>
          </div>
          {/* Scrollable content */}
          <div style={{ padding: '12px 16px', overflowY: 'auto' }}>{activeEntry.content}</div>
        </div>
      )}

      {/* Launcher button */}
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          position: 'fixed',
          bottom: '16px',
          left: '16px',
          zIndex: 500,
          backgroundColor: open ? '#f0ab00' : '#fff8e1',
          border: '2px solid #f9a825',
          borderRadius: '6px',
          padding: '6px 12px',
          fontSize: '13px',
          fontWeight: 600,
          color: '#1b1d21',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
          lineHeight: 1.5,
        }}
      >
        View design notes
      </button>
    </>
  );
}
