import {
  CopyCell,
  DateTimeCell,
  ITableColumn,
  PFColorE,
  TextCell,
  useGetPageUrl,
} from '@ansible/ansible-ui-framework';
import { StatusCell } from '@ansible/common-ui/Status';
import { CheckCircleIcon, ExclamationCircleIcon, ExclamationTriangleIcon } from '@patternfly/react-icons';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { HubRoute } from '../../../main/HubRoutes';
import { EeApproval } from '../EeApproval';

function signatureStatusForCell(status: EeApproval['signature_status']) {
  switch (status) {
    case 'signed':
      return 'successful';
    case 'unsigned':
      return 'failed';
    default:
      return 'unknown';
  }
}

export function useEeApprovalsColumns(options?: { disableLinks?: boolean }) {
  const { t } = useTranslation();
  const getPageUrl = useGetPageUrl();

  return useMemo<ITableColumn<EeApproval>[]>(
    () => [
      {
        header: t('Image'),
        cell: (approval) => <TextCell text={approval.image_name} />,
        card: 'name',
        list: 'name',
      },
      {
        header: t('Registry'),
        cell: (approval) => (
          <TextCell
            text={approval.registry_name}
            to={
              options?.disableLinks
                ? undefined
                : getPageUrl(HubRoute.RemoteRegistryDetails, {
                    params: { id: approval.registry_name },
                  })
            }
          />
        ),
      },
      {
        header: t('Tag'),
        cell: (approval) => <TextCell text={approval.tag} />,
        list: 'secondary',
      },
      {
        header: t('Digest'),
        cell: (approval) => <CopyCell text={approval.digest} />,
        list: 'secondary',
      },
      {
        header: t('Signature status'),
        cell: (approval) => (
          <StatusCell status={signatureStatusForCell(approval.signature_status)} />
        ),
      },
      {
        header: t('Status'),
        cell: (approval) => {
          if (approval.status === 'needs_review') {
            return (
              <TextCell
                icon={<ExclamationTriangleIcon />}
                text={t('Needs review')}
                color={PFColorE.Warning}
              />
            );
          }
          if (approval.status === 'approved') {
            return (
              <TextCell
                icon={<CheckCircleIcon />}
                text={t('Approved')}
                color={PFColorE.Success}
              />
            );
          }
          return (
            <TextCell icon={<ExclamationCircleIcon />} text={t('Rejected')} color={PFColorE.Red} />
          );
        },
      },
      {
        header: t('Submitted'),
        cell: (approval) => <DateTimeCell value={approval.submitted_at} />,
        list: 'secondary',
      },
      {
        header: t('Submitted by'),
        cell: (approval) => <TextCell text={approval.submitted_by} />,
        list: 'secondary',
      },
    ],
    [getPageUrl, options?.disableLinks, t]
  );
}
