import {
  PageFormSelect,
  PageFormSwitch,
  usePageAlertToaster,
  usePageDialog,
} from '@ansible/ansible-ui-framework';
import { PageFormFileUpload } from '@ansible/ansible-ui-framework/PageForm/Inputs/PageFormFileUpload';
import { createRequestError } from '@ansible/common-ui/crud/RequestError';
import { getCookie } from '@ansible/common-ui/crud/cookie';
import { Modal, ModalBody, ModalHeader, ModalVariant } from '@patternfly/react-core';
import { useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { HubPageForm } from '../../../common/HubPageForm';
import { hubAPI } from '../../../common/api/formatPath';
import { extractErrorDescription } from '../../../common/utils/errorUtils';
import { RemoteRegistry } from '../RemoteRegistry';

interface ImportBundleFormValues {
  file?: File;
  registry_id: string;
  verify_signatures: boolean;
}

async function postImportBundle(values: ImportBundleFormValues) {
  if (!values.file) {
    throw new Error('Bundle file is required');
  }

  const body = new FormData();
  body.append('file', values.file);
  body.append('registry_id', values.registry_id);
  body.append('verify_signatures', String(values.verify_signatures));

  const response = await fetch(hubAPI`/_ui/v1/execution-environments/registries/import-bundle/`, {
    method: 'POST',
    body,
    credentials: 'include',
    headers: {
      'X-CSRFToken': getCookie('csrftoken') ?? '',
    },
  });

  if (!response.ok) {
    throw await createRequestError(response);
  }

  return response.json() as Promise<{ message?: string; registry_id?: string }>;
}

export function useImportRegistryBundle(registries: RemoteRegistry[] = []) {
  const { t } = useTranslation();
  const [_, setDialog] = usePageDialog();
  const alertToaster = usePageAlertToaster();
  const onClose = useCallback(() => setDialog(undefined), [setDialog]);

  const registryOptions = useMemo(
    () => [
      {
        label: t('Create registry from bundle'),
        value: '__new__',
        description: t('Import creates a new registry connection from bundle metadata.'),
      },
      ...registries.map((registry) => ({
        label: registry.name,
        value: registry.id,
        description: registry.url,
      })),
    ],
    [registries, t]
  );

  const defaultValues = useMemo<ImportBundleFormValues>(
    () => ({
      registry_id: registries[0]?.id ?? '__new__',
      verify_signatures: true,
    }),
    [registries]
  );

  return useCallback(() => {
    setDialog(
      <Modal
        aria-label={t('Import bundle')}
        isOpen
        onClose={onClose}
        variant={ModalVariant.medium}
        tabIndex={0}
      >
        <ModalHeader
          title={t('Import bundle')}
          description={t(
            'Upload an offline content bundle to populate a registry in a disconnected environment. Signatures and metadata travel with the bundle per ANSTRAT-1758 M4.'
          )}
        />
        <ModalBody style={{ paddingLeft: 0 }}>
          <HubPageForm<ImportBundleFormValues>
            submitText={t('Import')}
            onCancel={onClose}
            defaultValue={defaultValues}
            singleColumn
            disablePadding
            disableSubmitOnEnter
            onSubmit={(values) =>
              postImportBundle(values)
                .then(() => {
                  alertToaster.addAlert({
                    variant: 'success',
                    title: t('Bundle import started'),
                    children: t(
                      'The import is running in the background. Refresh the registry list when complete.'
                    ),
                  });
                  onClose();
                })
                .catch((error: unknown) => {
                  alertToaster.addAlert({
                    variant: 'danger',
                    title: t('Failed to import bundle'),
                    children: extractErrorDescription(error),
                  });
                })
            }
          >
            <PageFormFileUpload
              name="file"
              label={t('Bundle file')}
              isRequired
              labelHelp={t('Offline export package (e.g. tar archive) produced from a connected Hub.')}
            />
            <PageFormSelect<ImportBundleFormValues>
              name="registry_id"
              label={t('Target registry')}
              isRequired
              options={registryOptions}
              placeholderText={t('Select a registry')}
              labelHelp={t(
                'Import into an existing registry or create a new registry from bundle metadata.'
              )}
            />
            <PageFormSwitch<ImportBundleFormValues>
              name="verify_signatures"
              label={t('Verify signatures')}
              labelHelp={t('Verify image signatures in the bundle before importing content.')}
              labelOn={t('Verify signatures before import')}
            />
          </HubPageForm>
        </ModalBody>
      </Modal>
    );
  }, [alertToaster, defaultValues, onClose, registryOptions, setDialog, t]);
}
