import { compareStrings } from '@ansible/ansible-ui-framework';
import { postRequest } from '@ansible/common-ui/crud/Data';
import { useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { hubAPI } from '../../../common/api/formatPath';
import { useHubBulkConfirmation } from '../../../common/useHubBulkConfirmation';
import { EeApproval } from '../EeApproval';
import { useEeApprovalsColumns } from './useEeApprovalsColumns';

function rejectEeApproval(approval: EeApproval) {
  return postRequest<{ updated: number }, { ids: string[] }>(
    hubAPI`/_ui/v1/execution-environments/approvals/reject/`,
    { ids: [approval.id] }
  );
}

export function useRejectEeApprovals(onComplete?: (approvals: EeApproval[]) => void) {
  const { t } = useTranslation();
  const confirmationColumns = useEeApprovalsColumns({ disableLinks: true });
  const actionColumns = useMemo(() => [confirmationColumns[0]], [confirmationColumns]);
  const bulkAction = useHubBulkConfirmation<EeApproval>();

  return useCallback(
    (approvals: EeApproval[]) => {
      bulkAction({
        title: t('Reject images', { count: approvals.length }),
        confirmText: t('Yes, I confirm that I want to reject these {{count}} images.', {
          count: approvals.length,
        }),
        actionButtonText: t('Reject images', { count: approvals.length }),
        items: [...approvals].sort((left, right) =>
          compareStrings(left.image_name, right.image_name)
        ),
        keyFn: (approval) => approval.id,
        isDanger: true,
        confirmationColumns,
        actionColumns,
        onComplete,
        actionFn: rejectEeApproval,
      });
    },
    [actionColumns, bulkAction, confirmationColumns, onComplete, t]
  );
}
