import {
  PageFormSubmitHandler,
  PageFormTextArea,
  PageFormTextInput,
  PageHeader,
  PageLayout,
  useGetPageUrl,
  usePageNavigate,
} from '@ansible/ansible-ui-framework';
import { LoadingPage } from '@ansible/ansible-ui-framework/components/LoadingPage';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useClearCache } from '@ansible/common-ui/useInvalidateCache/useInvalidateCache';
import { TFunction } from 'i18next';
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams, useSearchParams } from 'react-router-dom';
import { useRegisterPrototypeNotes } from '../../../platform/common/PrototypeNotesRegistry';
import { ExecutionEnvironmentPrototypeNote } from '../../../platform/src/prototype/registries/ExecutionEnvironmentPrototypeNotes';
import { isRegistriesPrototypeMode } from '../administration/remote-registries/registriesLabels';
import { RegistryImage } from '../administration/remote-registries/RegistryImage';
import { RemoteRegistry } from '../administration/remote-registries/RemoteRegistry';
import { useRemoteRegistriesColumns } from '../administration/remote-registries/hooks/useRemoteRegistriesColumns';
import { useRemoteRegistryFilters } from '../administration/remote-registries/hooks/useRemoteRegistryFilters';
import { PageFormChipsInput } from '../common/components/PageFormChipsInput';
import { TagsInputGroup } from '../common/components/TagsInputGroup';
import { HubError } from '../common/HubError';
import { HubPageForm } from '../common/HubPageForm';
import { PageFormSingleSelectHubResource } from '../common/PageFormSingleSelectHubResource';
import { hubErrorAdapter } from '../common/adapters/hubErrorAdapter';
import { hubAPI, pulpAPI } from '../common/api/formatPath';
import { hubAPIPatch, hubAPIPost, hubAPIPut } from '../common/api/hub-api-utils';
import { HubItemsResponse } from '../common/useHubView';
import { HubRoute } from '../main/HubRoutes';
import { PageFormRegistryImageSelect } from './components/PageFormRegistryImageSelect';
import { ExecutionEnvironment } from './ExecutionEnvironment';
import { useExecutionEnvironmentFilters } from './hooks/useExecutionEnvironmentFilters';
import { useExecutionEnvironmentsColumns } from './hooks/useExecutionEnvironmentsColumns';
import { useRegistryImageColumns } from './hooks/useRegistryImageColumns';

export function CreateExecutionEnvironment() {
  return <ExecutionEnvironmentForm mode="add" />;
}

export function EditExecutionEnvironment() {
  return <ExecutionEnvironmentForm mode="edit" />;
}

function ExecutionEnvironmentForm(props: Readonly<{ mode: 'add' | 'edit' }>) {
  const page_size = 50;
  const { t } = useTranslation();
  const navigate = usePageNavigate();
  const getPageUrl = useGetPageUrl();
  const mode = props.mode;
  const params = useParams<{ id?: string }>();
  const [searchParams] = useSearchParams();
  const { clearCacheByKey } = useClearCache();
  const isPrototype = isRegistriesPrototypeMode();

  const registryIdParam = searchParams.get('registryId');
  const imageParam = searchParams.get('image');
  const tagParam = searchParams.get('tag');

  const eeColumns = useExecutionEnvironmentsColumns({
    disableLinks: true,
  });
  const eeFilters = useExecutionEnvironmentFilters();
  const registryColumns = useRemoteRegistriesColumns({ disableLinks: true });
  const registryFilters = useRemoteRegistryFilters();
  const imageColumns = useRegistryImageColumns();

  const [tagsToInclude, setTagsToInclude] = useState<string[]>([]);
  const [tagsToExclude, setTagsToExclude] = useState<string[]>([]);
  const [tagsSet, setTagsSet] = useState<boolean>(false);
  const [prefillApplied, setPrefillApplied] = useState(false);

  const registry = useGet<HubItemsResponse<Registry>>(
    hubAPI`/_ui/v1/execution-environments/registries/?limit=${page_size}`
  );

  const prefillRegistry = useGet<Registry>(
    isPrototype && mode === 'add' && registryIdParam
      ? hubAPI`/_ui/v1/execution-environments/registries/${registryIdParam}/`
      : ''
  );

  const eeUrl =
    mode === 'edit' && params?.id
      ? hubAPI`/v3/plugin/execution-environments/repositories/${params?.id}/`
      : '';

  const executionEnvironment = useGet<ExecutionEnvironment>(eeUrl);

  const singleRegistryUrl =
    mode === 'edit' && executionEnvironment.data?.pulp?.repository?.remote?.registry
      ? hubAPI`/_ui/v1/execution-environments/registries/${executionEnvironment.data?.pulp?.repository?.remote?.registry}/`
      : '';

  const singleRegistry = useGet<Registry>(singleRegistryUrl);

  const isNew = !executionEnvironment.data?.pulp?.repository;
  const isRemote = executionEnvironment.data?.pulp?.repository
    ? !!executionEnvironment.data?.pulp?.repository?.remote
    : true;

  const isLoading =
    ((!executionEnvironment.data || (isRemote && singleRegistryUrl && !singleRegistry.data)) &&
      mode === 'edit') ||
    (isPrototype && mode === 'add' && registryIdParam && !prefillRegistry.data);

  if (mode === 'edit' && !tagsSet && isLoading === false) {
    setTagsSet(true);
    setTagsToExclude(executionEnvironment.data?.pulp?.repository?.remote?.exclude_tags || []);
    setTagsToInclude(executionEnvironment.data?.pulp?.repository?.remote?.include_tags || []);
  }

  useRegisterPrototypeNotes({
    id: 'create-execution-environment',
    title: t('Create execution environment'),
    content:
      isPrototype && mode === 'add' ? <ExecutionEnvironmentPrototypeNote defaultOpen /> : null,
  });

  useEffect(() => {
    if (!isPrototype || mode !== 'add' || prefillApplied || !prefillRegistry.data) {
      return;
    }
    if (tagParam) {
      setTagsToInclude([tagParam]);
    }
    setPrefillApplied(true);
  }, [imageParam, isPrototype, mode, prefillApplied, prefillRegistry.data, tagParam]);

  const handleImageSelected = (image: RegistryImage) => {
    if (image.tags.length > 0 && tagsToInclude.length === 0) {
      setTagsToInclude([image.tags[0]]);
    }
  };

  const onSubmit: PageFormSubmitHandler<ExecutionEnvironmentFormProps> = async (
    formData: ExecutionEnvironmentFormProps
  ) => {
    const payload: PayloadDataType = {
      exclude_tags: tagsToExclude,
      include_tags: tagsToInclude,
      name: formData.name,
      upstream_name: formData.upstream_name,
      registry: formData.registry?.id || '',
      ...(isPrototype ? { governance_labels: formData.governance_labels ?? [] } : {}),
    };

    if (isRemote && isNew) {
      await hubAPIPost<ExecutionEnvironmentFormProps>(
        hubAPI`/_ui/v1/execution-environments/remotes/`,
        payload
      );
    } else {
      if (isRemote && !isNew) {
        await hubAPIPut<ExecutionEnvironment>(
          hubAPI`/_ui/v1/execution-environments/remotes/${
            executionEnvironment.data?.pulp?.repository?.remote?.id ?? ''
          }/`,
          payload
        );
        clearCacheByKey(hubAPI`/_ui/v1/execution-environments/remotes/`);
      }

      if (formData.description !== executionEnvironment.data?.description) {
        await hubAPIPatch(
          pulpAPI`/distributions/container/container/${
            executionEnvironment.data?.pulp?.distribution?.id ?? ''
          }/`,
          { description: formData.description ?? null }
        );
        clearCacheByKey(pulpAPI`/distributions/container/container/`);
      }
    }

    void navigate(HubRoute.ExecutionEnvironmentDetails, {
      params: { id: formData.name },
    });
  };

  const defaultFormValue = useMemo(
    () => ({
      name: executionEnvironment.data?.name,
      upstream_name:
        imageParam ??
        executionEnvironment.data?.pulp?.repository?.remote?.upstream_name ??
        undefined,
      description: executionEnvironment.data?.description,
      registry: prefillRegistry.data
        ? { id: prefillRegistry.data.id, name: prefillRegistry.data.name }
        : { id: singleRegistry.data?.id, name: singleRegistry.data?.name },
      namespace: executionEnvironment.data?.namespace,
      governance_labels: executionEnvironment.data?.governance_labels ?? [],
    }),
    [
      executionEnvironment.data?.description,
      executionEnvironment.data?.name,
      executionEnvironment.data?.namespace,
      executionEnvironment.data?.pulp?.repository?.remote?.upstream_name,
      imageParam,
      prefillRegistry.data,
      singleRegistry.data?.id,
      singleRegistry.data?.name,
    ]
  );

  if (isLoading) return <LoadingPage breadcrumbs tabs />;
  if (registry.error) return <HubError error={registry.error} handleRefresh={registry.refresh} />;
  if (executionEnvironment.error)
    return (
      <HubError error={executionEnvironment.error} handleRefresh={executionEnvironment.refresh} />
    );
  if (singleRegistry.error)
    return <HubError error={singleRegistry.error} handleRefresh={singleRegistry.refresh} />;
  if (prefillRegistry.error)
    return <HubError error={prefillRegistry.error} handleRefresh={prefillRegistry.refresh} />;

  return (
    <PageLayout>
      <PageHeader
        title={
          props.mode === 'edit'
            ? t('Edit {{executionenvironmentName}}', {
                executionenvironmentName: executionEnvironment.data?.name,
              })
            : t('Create execution environment')
        }
        breadcrumbs={
          props.mode === 'edit'
            ? [
                {
                  label: t('Execution Environments'),
                  to: getPageUrl(HubRoute.ExecutionEnvironments),
                },
                {
                  label: t('Edit {{executionenvironmentName}}', {
                    executionenvironmentName: executionEnvironment.data?.name,
                  }),
                },
              ]
            : [
                {
                  label: t('Execution Environments'),
                  to: getPageUrl(HubRoute.ExecutionEnvironments),
                },
                { label: t('Create execution environment') },
              ]
        }
      />

      {!isLoading && (
        <HubPageForm<ExecutionEnvironmentFormProps>
          submitText={
            props.mode === 'edit'
              ? t('Save execution environment')
              : t('Create execution environment')
          }
          onCancel={() => void navigate(HubRoute.ExecutionEnvironments)}
          onSubmit={onSubmit}
          defaultValue={defaultFormValue}
          disableSubmitOnEnter={true}
          errorAdapter={(error) => hubErrorAdapter(error, { base_path: 'name' })}
        >
          <PageFormTextInput<ExecutionEnvironmentFormProps>
            name="name"
            label={t('Name')}
            placeholder={t('Enter execution environment name')}
            isRequired
            isDisabled={mode === 'edit' || !isRemote}
            validate={(name: string) => validateName(name, t)}
          />

          {!isRemote && (
            <PageFormTextInput<ExecutionEnvironmentFormProps>
              name="namespace.name"
              label={t('Namespace')}
              placeholder={t('Enter namespace name')}
              isDisabled
            />
          )}

          {!isNew && (
            <PageFormTextArea<ExecutionEnvironmentFormProps>
              name="description"
              label={t('Description')}
              placeholder={t('Enter description')}
            />
          )}

          {isRemote && (
            <>
              {isPrototype ? (
                <PageFormSingleSelectHubResource<RemoteRegistry>
                  name="registry"
                  label={t('Registry')}
                  placeholder={t('Select registry')}
                  queryPlaceholder={t('Loading registry...')}
                  queryErrorText={t('Error loading registry')}
                  isRequired={true}
                  url={hubAPI`/_ui/v1/execution-environments/registries/`}
                  tableColumns={registryColumns}
                  toolbarFilters={registryFilters}
                />
              ) : (
                <PageFormSingleSelectHubResource<ExecutionEnvironment>
                  name="registry"
                  label={t('Registry')}
                  placeholder={t('Select registry')}
                  queryPlaceholder={t('Loading registry...')}
                  queryErrorText={t('Error loading registry')}
                  isRequired={true}
                  url={hubAPI`/_ui/v1/execution-environments/registries/`}
                  tableColumns={eeColumns}
                  toolbarFilters={eeFilters}
                />
              )}
              {isPrototype && mode === 'add' ? (
                <PageFormRegistryImageSelect<ExecutionEnvironmentFormProps>
                  name="upstream_name"
                  tableColumns={imageColumns}
                  onImageSelected={handleImageSelected}
                />
              ) : (
                <PageFormTextInput<ExecutionEnvironmentFormProps>
                  name="upstream_name"
                  label={t('Upstream name')}
                  placeholder={t('Enter upstream name')}
                  isRequired
                />
              )}
              <TagsInputGroup tags={tagsToInclude} setTags={setTagsToInclude} mode="include" />
              <TagsInputGroup tags={tagsToExclude} setTags={setTagsToExclude} mode="exclude" />
              {isPrototype ? (
                <PageFormChipsInput<ExecutionEnvironmentFormProps>
                  name="governance_labels"
                  fieldId="ee-governance-labels"
                  label={t('Labels')}
                  labelHelp={t(
                    'Governance metadata for this execution environment (not image tags like latest). Type a label and press Enter.'
                  )}
                />
              ) : null}
            </>
          )}
        </HubPageForm>
      )}
    </PageLayout>
  );
}

function validateName(name: string, t: TFunction<'translation', undefined>) {
  const regex = /^([0-9A-Za-z._-]+\/)?[0-9A-Za-z._-]+$/;
  if (regex.test(name)) {
    return undefined;
  } else {
    return t(
      `Container names can only contain alphanumeric characters, ".", "_", "-" and up to one "/".`
    );
  }
}

type ExecutionEnvironmentFormProps = {
  name: string;
  upstream_name: string;
  description?: string;
  registry: Registry;
  namespace?: { name: string };
  governance_labels?: string[];
};

export type PayloadDataType = {
  include_tags?: string[];
  exclude_tags?: string[];
  name: string;
  upstream_name: string;
  registry: string;
  governance_labels?: string[];
};

type Registry = {
  id: string;
  name: string;
};
