import {
  ColumnTableOption,
  CopyCell,
  ITableColumn,
  TextCell,
  useGetPageUrl,
} from '@ansible/ansible-ui-framework';
import { StatusCell } from '@ansible/common-ui/Status';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { HubRoute } from '../../../main/HubRoutes';
import { RemoteRegistry } from '../RemoteRegistry';
import { isRegistriesPrototypeMode } from '../registriesLabels';

function connectionStatusForCell(status?: RemoteRegistry['connection_status']) {
  switch (status) {
    case 'connected':
      return 'successful';
    case 'failed':
      return 'failed';
    default:
      return 'unknown';
  }
}

export function useRemoteRegistriesColumns(_options?: {
  disableSort?: boolean;
  disableLinks?: boolean;
}) {
  const { t } = useTranslation();
  const getPageUrl = useGetPageUrl();
  const isPrototype = isRegistriesPrototypeMode();
  const tableColumns = useMemo<ITableColumn<RemoteRegistry>[]>(
    () => [
      {
        header: t('Name'),
        cell: (remoteRegistry) => (
          <TextCell
            text={remoteRegistry.name}
            to={getPageUrl(HubRoute.RemoteRegistryDetails, { params: { id: remoteRegistry.name } })}
          />
        ),
        sort: 'name',
        card: 'name',
        list: 'name',
      },
      ...(isPrototype
        ? [
            {
              header: t('Connection status'),
              cell: (remoteRegistry: RemoteRegistry) => (
                <StatusCell status={connectionStatusForCell(remoteRegistry.connection_status)} />
              ),
              table: ColumnTableOption.expanded,
              list: 'secondary',
            } as ITableColumn<RemoteRegistry>,
            {
              header: t('Image count'),
              cell: (remoteRegistry: RemoteRegistry) => (
                <TextCell text={String(remoteRegistry.image_count ?? 0)} />
              ),
              list: 'secondary',
            } as ITableColumn<RemoteRegistry>,
          ]
        : []),
      {
        header: t('Sync status'),
        cell: (remoteRegistry) => {
          if (
            remoteRegistry.last_sync_task &&
            Object.keys(remoteRegistry.last_sync_task).length > 0 &&
            remoteRegistry.last_sync_task.state
          ) {
            return <StatusCell status={remoteRegistry.last_sync_task.state} />;
          }
          return <TextCell text={t('Never synced')} />;
        },
      },
      {
        header: t('Last sync'),
        type: 'datetime',
        value: (remoteRegistry) => remoteRegistry.last_sync_task?.finished_at,
        list: 'secondary',
      },
      {
        header: t('URL'),
        cell: (remoteRegistry) => <CopyCell text={remoteRegistry.url} />,
      },
      {
        header: t('Created'),
        type: 'datetime',
        value: (remoteRegistry) => remoteRegistry.created_at,
        table: ColumnTableOption.expanded,
        card: 'hidden',
        list: 'secondary',
      },
      {
        header: t('Last modified'),
        type: 'datetime',
        value: (remoteRegistry) => remoteRegistry.updated_at,
        table: ColumnTableOption.expanded,
        card: 'hidden',
        list: 'secondary',
      },
    ],
    [getPageUrl, isPrototype, t]
  );
  return tableColumns;
}
