import { PageTable, PageHeader, PageLayout } from '@ansible/ansible-ui-framework';
import { useTranslation } from 'react-i18next';
import { useRegisterPrototypeNotes } from '../../../../platform/common/PrototypeNotesRegistry';
import { EeApprovalsPrototypeNote } from '../../../../platform/src/prototype/registries/EeApprovalsPrototypeNotes';
import { hubAPI } from '../../common/api/formatPath';
import { useHubView } from '../../common/useHubView';
import { EeApproval } from './EeApproval';
import { useEeApprovalActions, useEeApprovalsToolbarActions } from './hooks/useEeApprovalActions';
import { useEeApprovalFilters } from './hooks/useEeApprovalFilters';
import { useEeApprovalsColumns } from './hooks/useEeApprovalsColumns';

export function EeApprovals() {
  const { t } = useTranslation();
  const toolbarFilters = useEeApprovalFilters();
  const tableColumns = useEeApprovalsColumns();

  useRegisterPrototypeNotes({
    id: 'ee-approvals',
    title: t('Execution Environment Approvals'),
    content: <EeApprovalsPrototypeNote defaultOpen />,
  });

  const view = useHubView<EeApproval>({
    url: hubAPI`/_ui/v1/execution-environments/approvals/`,
    keyFn: (approval) => approval.id,
    toolbarFilters,
    tableColumns,
    defaultFilters: { status: ['needs_review'] },
  });

  const rowActions = useEeApprovalActions(view.unselectItemsAndRefresh);
  const toolbarActions = useEeApprovalsToolbarActions(view.unselectItemsAndRefresh);

  const description = t(
    'Review execution environment images before they are available for use in automation jobs.'
  );

  return (
    <PageLayout>
      <PageHeader
        title={t('Execution Environment Approvals')}
        description={description}
        titleHelpTitle={t('Execution Environment Approvals')}
        titleHelp={description}
      />
      <PageTable<EeApproval>
        id="hub-ee-approvals-table"
        toolbarFilters={toolbarFilters}
        tableColumns={tableColumns}
        rowActions={rowActions}
        toolbarActions={toolbarActions}
        errorStateTitle={t('Error loading execution environment approvals')}
        emptyStateTitle={t('No execution environment approvals yet')}
        emptyStateDescription={t(
          'Images pending review will appear here after they are submitted for approval.'
        )}
        defaultSubtitle={t('EE Approval')}
        {...view}
      />
    </PageLayout>
  );
}
