import { ColumnModalOption, ColumnTableOption, ITableColumn, TextCell, useGetPageUrl } from '@ansible/ansible-ui-framework';
import { Label } from '@patternfly/react-core';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { isRegistriesPrototypeMode } from '../../administration/remote-registries/registriesLabels';
import { HubRoute } from '../../main/HubRoutes';

import { ExecutionEnvironment } from '../ExecutionEnvironment';
import { GovernanceLabelGroup } from '../governanceLabels';
import { SignStatus } from '../ExecutionEnvironmentPage/components/SignStatus';

export function useExecutionEnvironmentsColumns(_options?: {
  disableSort?: boolean;
  disableLinks?: boolean;
}) {
  const { t } = useTranslation();
  const getPageUrl = useGetPageUrl();
  const isPrototype = isRegistriesPrototypeMode();

  const tableColumns = useMemo<ITableColumn<ExecutionEnvironment>[]>(
    () => [
      {
        header: t('Name'),
        cell: (executionEnvironment) => (
          <TextCell
            text={executionEnvironment.name}
            to={
              _options?.disableLinks
                ? undefined
                : getPageUrl(HubRoute.ExecutionEnvironmentDetails, {
                    params: { id: executionEnvironment.name },
                  })
            }
          />
        ),
        value: (executionEnvironment) => executionEnvironment.name,
        card: 'name',
        list: 'name',
        sort: 'name',
      },
      {
        header: t('Description'),
        type: 'description',
        value: (executionEnvironment) => executionEnvironment.description ?? undefined,
        card: 'description',
        list: 'description',
        table: ColumnTableOption.description,
        modal: ColumnModalOption.hidden,
        sort: 'description',
      },
      {
        header: t('Created'),
        type: 'datetime',
        value: (executionEnvironment) => executionEnvironment.created_at,
        card: 'hidden',
        list: 'secondary',
        sort: 'created_at',
      },
      {
        header: t('Last modified'),
        type: 'datetime',
        value: (executionEnvironment) => executionEnvironment.updated_at,
        card: 'hidden',
        list: 'secondary',
        sort: 'updated_at',
      },
      {
        header: t('Signature status'),
        cell: (ee) => <SignStatus state={ee.pulp?.repository?.sign_state} />,
        list: 'secondary',
      },
      ...(isPrototype
        ? [
            {
              header: t('Labels'),
              cell: (ee: ExecutionEnvironment) => <GovernanceLabelGroup labels={ee.governance_labels} />,
              list: 'secondary',
            } as ITableColumn<ExecutionEnvironment>,
          ]
        : []),
      {
        header: t('Container registry type'),
        cell: (ee) => <Label>{ee.pulp?.repository?.remote ? t`Remote` : t`Local`}</Label>,
        list: 'secondary',
      },
    ],
    [_options?.disableLinks, getPageUrl, isPrototype, t]
  );
  return tableColumns;
}
