import { IToolbarFilter, ToolbarFilterType } from '@ansible/ansible-ui-framework';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';

export function useRegistryImagesFilters() {
  const { t } = useTranslation();

  return useMemo<IToolbarFilter[]>(
    () => [
      {
        key: 'name',
        label: t('Name'),
        type: ToolbarFilterType.SingleText,
        query: 'name',
        comparison: 'contains',
        placeholder: t('Filter by name'),
      },
      {
        key: 'signature_status',
        label: t('Signature status'),
        type: ToolbarFilterType.SingleSelect,
        query: 'signature_status',
        placeholder: t('Select signature status'),
        options: [
          { value: 'signed', label: t('Signed') },
          { value: 'unsigned', label: t('Unsigned') },
          { value: 'unverified', label: t('Unverified') },
          { value: 'failed', label: t('Verification failed') },
        ],
      },
    ],
    [t]
  );
}
