import { ITableColumn, TextCell } from '@ansible/ansible-ui-framework';
import { StatusCell } from '@ansible/common-ui/Status';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { RegistryImage } from '../../administration/remote-registries/RegistryImage';

function signatureStatusForCell(status: RegistryImage['signature_status']) {
  switch (status) {
    case 'signed':
      return 'successful';
    case 'unsigned':
      return 'failed';
    default:
      return 'unknown';
  }
}

export function useRegistryImageColumns() {
  const { t } = useTranslation();

  return useMemo<ITableColumn<RegistryImage>[]>(
    () => [
      {
        header: t('Name'),
        cell: (image) => <TextCell text={image.name} />,
        card: 'name',
        list: 'name',
      },
      {
        header: t('Tags'),
        cell: (image) => <TextCell text={image.tags.join(', ')} />,
      },
      {
        header: t('Signature status'),
        cell: (image) => <StatusCell status={signatureStatusForCell(image.signature_status)} />,
      },
      {
        header: t('Architecture'),
        cell: (image) => <TextCell text={image.architecture ?? t('Not specified')} />,
      },
      {
        header: t('Last updated'),
        type: 'datetime',
        value: (image) => image.last_updated,
      },
    ],
    [t]
  );
}
