import { PrototypeNote } from '../../../common/PrototypeNote';

export function EeApprovalsPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>This page mirrors the Collection Approvals pattern but is separate
          until a unified approvals API exists.
        </>,
        <>
          Backend required:{' '}
          <code>GET /api/galaxy/_ui/v1/execution-environments/approvals/</code> plus approve/reject
          endpoints — shape is assumed for ANSTRAT-1758.
        </>,
        <>
          <strong>Signature status</strong> column is read-only here (Signed / Unsigned /
          Unverified). Signing is initiated from the EE detail kebab after the EE exists — not from
          the approvals queue in this prototype.
        </>,
        <>
          <strong>Labels</strong> (governance metadata, not image tags like <code>latest</code>) are
          set on the <strong>EE create/edit form</strong> in this prototype — a multi-select field
          with admin-defined values (e.g.&nbsp;<code>production</code>, <code>dev</code>). Labels
          display as chips on EE detail and list. Allowed values would come from Hub settings (not
          yet prototyped).
        </>,
        <>
          Approve/reject decisions should eventually appear in a <strong>platform-level audit
          log</strong>. A per-queue decision log tab is optional for the prototype.
        </>,
        <>
          <strong>SDP Q20 — industry pattern:</strong> Human approval is usually{' '}
          <strong>policy-based</strong> (per registry or namespace), not mandatory for every image.
          Regulated customers may require mandatory gates. Prototype assumes opt-in per registry until
          stakeholders decide.
        </>,
      ]}
      questions={[
        'Is approval per image tag, per digest, or per EE definition?',
        'Should Execution Environment Approvals and Collection Approvals eventually merge into one tabbed Approvals page?',
        'Does signature verification on the registry auto-reject, or only flag for human review?',
        'If an approved image is re-tagged or replaced externally in the registry after approval, does the approval still hold — or should Hub revoke it and require re-review?',
        'Are governance labels a fixed taxonomy (production, staging) or admin-defined at runtime?',
        'Should labels be set only on the EE form, or also (or instead) in the Approve modal — e.g. require reviewer to apply production before approval completes?',
        'Should "Sign on approve" be supported, or keep sign as a separate EE detail action?',
        'SDP Q20: Must every synced image pass approval before developers can use it, or is approval opt-in per registry?',
      ]}
    />
  );
}
