import {
  IPageAction,
  PageActionSelection,
  PageActionType,
  PageTable,
  usePageNavigate,
} from '@ansible/ansible-ui-framework';
import { PlusCircleIcon } from '@patternfly/react-icons';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useOutletContext } from 'react-router-dom';
import { useRegisterPrototypeNotes } from '../../../../../platform/common/PrototypeNotesRegistry';
import { RegistryImagesPrototypeNote } from '../../../../../platform/src/prototype/registries/RegistryImagesPrototypeNotes';
import { hubAPI } from '../../../common/api/formatPath';
import { useHubView } from '../../../common/useHubView';
import { HubRoute } from '../../../main/HubRoutes';
import { isRegistriesPrototypeMode } from '../registriesLabels';
import { RegistryImage } from '../RegistryImage';
import { RemoteRegistry } from '../RemoteRegistry';
import { useRegistryImagesColumns } from './hooks/useRegistryImagesColumns';
import { useRegistryImagesFilters } from './hooks/useRegistryImagesFilters';

export function RegistryImages() {
  const { t } = useTranslation();
  const { remoteRegistry } = useOutletContext<{ remoteRegistry?: RemoteRegistry }>();
  const isPrototype = isRegistriesPrototypeMode();
  const toolbarFilters = useRegistryImagesFilters();
  const tableColumns = useRegistryImagesColumns();

  useRegisterPrototypeNotes({
    id: 'hub-registries-images',
    title: t('Images'),
    content: isPrototype ? <RegistryImagesPrototypeNote /> : null,
  });

  const view = useHubView<RegistryImage>({
    url: remoteRegistry?.id
      ? hubAPI`/_ui/v1/execution-environments/registries/${remoteRegistry.id}/images/`
      : '',
    keyFn: (image) => image.id,
    toolbarFilters,
    tableColumns,
  });

  const rowActions = useRegistryImageRowActions(remoteRegistry);

  return (
    <PageTable<RegistryImage>
      id="hub-registry-images-table"
      toolbarFilters={toolbarFilters}
      tableColumns={tableColumns}
      rowActions={rowActions}
      errorStateTitle={t('Error loading images')}
      emptyStateTitle={t('No images found')}
      emptyStateDescription={t('This registry does not have any discoverable images yet.')}
      defaultSubtitle={t('Image')}
      {...view}
    />
  );
}

function useRegistryImageRowActions(registry?: RemoteRegistry) {
  const { t } = useTranslation();
  const pageNavigate = usePageNavigate();
  const isPrototype = isRegistriesPrototypeMode();

  return useMemo<IPageAction<RegistryImage>[]>(() => {
    if (!isPrototype || !registry) {
      return [];
    }
    return [
      {
        type: PageActionType.Button,
        selection: PageActionSelection.Single,
        icon: PlusCircleIcon,
        label: t('Create execution environment'),
        isPinned: true,
        onClick: (image) => {
          pageNavigate(HubRoute.CreateExecutionEnvironment, {
            query: {
              registryId: registry.id,
              image: image.name,
              tag: image.tags[0] ?? '',
            },
          });
        },
      },
    ];
  }, [isPrototype, pageNavigate, registry, t]);
}
