import { PageTable, useInMemoryView } from '@ansible/ansible-ui-framework';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useTranslation } from 'react-i18next';
import { useOutletContext } from 'react-router-dom';
import { useRegisterPrototypeNotes } from '../../../../../platform/common/PrototypeNotesRegistry';
import { RegistrySyncHistoryPrototypeNote } from '../../../../../platform/src/prototype/registries/RegistrySyncHistoryPrototypeNotes';
import { hubAPI } from '../../../common/api/formatPath';
import { HubItemsResponse } from '../../../common/useHubView';
import { isRegistriesPrototypeMode } from '../registriesLabels';
import { RemoteRegistry } from '../RemoteRegistry';
import {
  useRegistrySyncHistoryColumns,
  type RegistrySyncHistoryEntry,
} from './hooks/useRegistrySyncHistoryColumns';
import { useRegistrySyncHistoryFilters } from './hooks/useRegistrySyncHistoryFilters';

export function RegistrySyncHistory() {
  const { t } = useTranslation();
  const { remoteRegistry } = useOutletContext<{ remoteRegistry?: RemoteRegistry }>();
  const isPrototype = isRegistriesPrototypeMode();
  const toolbarFilters = useRegistrySyncHistoryFilters();
  const tableColumns = useRegistrySyncHistoryColumns();

  useRegisterPrototypeNotes({
    id: 'hub-registries-sync-history',
    title: t('Sync History'),
    content: isPrototype ? <RegistrySyncHistoryPrototypeNote /> : null,
  });

  const historyUrl = remoteRegistry?.id
    ? hubAPI`/_ui/v1/execution-environments/registries/${remoteRegistry.id}/sync-history/`
    : '';

  const { data, error } = useGet<HubItemsResponse<RegistrySyncHistoryEntry>>(historyUrl);

  const view = useInMemoryView<RegistrySyncHistoryEntry>({
    items: data?.data,
    keyFn: (entry) => entry.id,
    toolbarFilters,
    tableColumns,
    error,
    defaultSort: 'started_at',
    defaultSortDirection: 'desc',
  });

  return (
    <PageTable<RegistrySyncHistoryEntry>
      id="hub-registry-sync-history-table"
      toolbarFilters={toolbarFilters}
      tableColumns={tableColumns}
      errorStateTitle={t('Error loading sync history')}
      emptyStateTitle={t('No sync history')}
      emptyStateDescription={t('Sync this registry to see history here.')}
      defaultSubtitle={t('Sync')}
      {...view}
    />
  );
}
