import { Label, LabelGroup } from '@patternfly/react-core';

export const GOVERNANCE_LABEL_OPTIONS = [
  { label: 'production', value: 'production' },
  { label: 'staging', value: 'staging' },
  { label: 'development', value: 'development' },
  { label: 'security-reviewed', value: 'security-reviewed' },
] as const;

export function GovernanceLabelGroup({ labels }: Readonly<{ labels?: string[] }>) {
  if (!labels?.length) {
    return null;
  }

  return (
    <LabelGroup numLabels={6}>
      {labels.map((label) => (
        <Label key={label} color="blue">
          {label}
        </Label>
      ))}
    </LabelGroup>
  );
}
