import {
  PageFormSelect,
  PageFormSwitch,
  PageFormTextInput,
} from '@ansible/ansible-ui-framework';
import { PageFormMultiSelect } from '@ansible/ansible-ui-framework/PageForm/Inputs/PageFormMultiSelect';
import { PageFormSecret } from '@ansible/ansible-ui-framework/PageForm/Inputs/PageFormSecret';
import { PageFormWatch } from '@ansible/ansible-ui-framework/PageForm/Utils/PageFormWatch';
import { useMemo } from 'react';
import { useFormContext } from 'react-hook-form';
import { useTranslation } from 'react-i18next';
import { TagsInputGroup } from '../../common/components/TagsInputGroup';
import { isRegistriesPrototypeMode } from './registriesLabels';
import { RemoteRegistry } from './RemoteRegistry';

interface RemoteRegistryFormValues extends RemoteRegistry {
  client_key?: string | null;
  password?: string | null;
  proxy_password?: string | null;
  proxy_username?: string | null;
  username?: string | null;
  token?: string | null;
}

interface RegistryPrototypeFormFieldsProps {
  onClear?: (name: string) => void;
  shouldHideField?: (name: string) => boolean;
}

function RegistrySyncScopeFields() {
  const { t } = useTranslation();
  const { watch, setValue } = useFormContext<RemoteRegistryFormValues>();
  const includeTags = watch('include_tags') ?? [];
  const excludeTags = watch('exclude_tags') ?? [];

  const architectureOptions = useMemo(
    () => [
      { label: t('amd64'), value: 'amd64' },
      { label: t('arm64'), value: 'arm64' },
      { label: t('ppc64le'), value: 'ppc64le' },
      { label: t('s390x'), value: 's390x' },
    ],
    [t]
  );

  return (
    <>
      <TagsInputGroup
        mode="include"
        tags={includeTags}
        setTags={(tags) => setValue('include_tags', tags)}
        fieldId="registry-include-tags"
      />
      <TagsInputGroup
        mode="exclude"
        tags={excludeTags}
        setTags={(tags) => setValue('exclude_tags', tags)}
        fieldId="registry-exclude-tags"
      />
      <PageFormMultiSelect<RemoteRegistryFormValues>
        name="include_architectures"
        label={t('Architectures to sync')}
        labelHelp={t(
          'Limit which CPU architectures Hub pulls during sync. Leave empty to sync all architectures.'
        )}
        options={architectureOptions}
        placeholder={t('Select architectures')}
      />
    </>
  );
}

export function RegistryPrototypeFormFields({
  onClear,
  shouldHideField,
}: Readonly<RegistryPrototypeFormFieldsProps>) {
  const { t } = useTranslation();

  const updatePolicyOptions = useMemo(
    () => [
      {
        label: t('Full refresh'),
        value: 'full',
        description: t(
          'Reconcile all image metadata with the registry. Removes local items that no longer exist upstream.'
        ),
      },
      {
        label: t('Incremental'),
        value: 'incremental',
        description: t('Fetch changes since the last sync. Recommended for routine updates.'),
      },
      {
        label: t('Newer only'),
        value: 'newer_only',
        description: t(
          'Only pull images or tags newer than what Hub already has. Skips unchanged content.'
        ),
      },
    ],
    [t]
  );

  if (!isRegistriesPrototypeMode()) {
    return null;
  }

  return (
    <>
      <PageFormSelect<RemoteRegistryFormValues>
        name="auth_type"
        label={t('Authentication type')}
        options={[
          { label: t('Basic'), value: 'basic' },
          { label: t('Token'), value: 'token' },
        ]}
        placeholderText={t('Select authentication type')}
      />
      <PageFormWatch<RemoteRegistryFormValues, 'auth_type'> watch="auth_type">
        {(authType) =>
          authType === 'token' ? (
            <PageFormSecret
              onClear={() => {
                onClear?.('token');
              }}
              shouldHideField={shouldHideField?.('token')}
            >
              <PageFormTextInput<RemoteRegistryFormValues>
                type="password"
                name="token"
                label={t('Token')}
                placeholder={t('Enter token')}
                labelHelp={t('Bearer token for registry authentication.')}
              />
            </PageFormSecret>
          ) : (
            <>
              <PageFormSecret
                onClear={() => {
                  onClear?.('username');
                }}
                shouldHideField={shouldHideField?.('username')}
              >
                <PageFormTextInput<RemoteRegistryFormValues>
                  name="username"
                  label={t('Username')}
                  placeholder={t('Enter username')}
                  labelHelp={t('The username for authentication when syncing.')}
                />
              </PageFormSecret>
              <PageFormSecret
                onClear={() => {
                  onClear?.('password');
                }}
                shouldHideField={shouldHideField?.('password')}
              >
                <PageFormTextInput<RemoteRegistryFormValues>
                  type="password"
                  name="password"
                  label={t('Password')}
                  placeholder={t('Enter password')}
                  labelHelp={t('The password for authentication when syncing.')}
                />
              </PageFormSecret>
            </>
          )
        }
      </PageFormWatch>
      <PageFormSelect<RemoteRegistryFormValues>
        name="sync_schedule"
        label={t('Sync schedule')}
        labelHelp={t(
          'How often Hub checks this registry for updates. Schedule UX is a prototype placeholder.'
        )}
        options={[
          { label: t('Manual'), value: 'manual' },
          { label: t('Daily'), value: 'daily' },
          { label: t('Weekly'), value: 'weekly' },
          { label: t('Custom'), value: 'custom' },
        ]}
        placeholderText={t('Select sync schedule')}
      />
      <PageFormSelect<RemoteRegistryFormValues>
        name="update_policy"
        label={t('Update policy')}
        labelHelp={t('Default behavior when this registry is synced.')}
        options={updatePolicyOptions}
        placeholderText={t('Select update policy')}
      />
      <RegistrySyncScopeFields />
      <PageFormSwitch<RemoteRegistryFormValues>
        name="signature_verification_enabled"
        label={t('Signature verification')}
        labelOn={t('Require signed images')}
        labelHelp={t(
          'When enabled, Hub checks each image for a valid signature during sync and blocks unsigned images from this registry.'
        )}
      />
    </>
  );
}
