import { useFormContext } from 'react-hook-form';
import { FieldValues, Path } from 'react-hook-form';
import { FormChipsInput } from './FormChipsInput';

export function PageFormChipsInput<TFieldValues extends FieldValues>(
  props: Readonly<{
    name: Path<TFieldValues>;
    label: string;
    labelHelp?: string;
    fieldId: string;
    placeholder?: string;
  }>
) {
  const { name, label, labelHelp, fieldId, placeholder } = props;
  const { watch, setValue } = useFormContext<TFieldValues>();
  const chips = (watch(name) as string[] | undefined) ?? [];

  return (
    <FormChipsInput
      label={label}
      labelHelp={labelHelp}
      chips={chips}
      onChipsChange={(nextChips) => setValue(name, nextChips as TFieldValues[Path<TFieldValues>])}
      fieldId={fieldId}
      placeholder={placeholder}
    />
  );
}
