import { IToolbarFilter, ToolbarFilterType } from '@ansible/ansible-ui-framework';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { isRegistriesPrototypeMode } from '../registriesLabels';

export function useRemoteRegistryFilters() {
  const { t } = useTranslation();
  const isPrototype = isRegistriesPrototypeMode();

  const toolbarFilters = useMemo<IToolbarFilter[]>(
    () => [
      {
        key: 'name',
        label: t('Name'),
        type: ToolbarFilterType.SingleText,
        query: 'name__icontains',
        comparison: 'contains',
      },
      {
        key: 'url',
        label: t('URL'),
        type: ToolbarFilterType.SingleText,
        query: 'url__icontains',
        comparison: 'contains',
      },
      ...(isPrototype
        ? [
            {
              key: 'connection_status',
              label: t('Connection status'),
              type: ToolbarFilterType.SingleSelect,
              query: 'connection_status',
              placeholder: t('Select connection status'),
              options: [
                { value: 'connected', label: t('Connected') },
                { value: 'failed', label: t('Failed') },
                { value: 'unknown', label: t('Unknown') },
              ],
            } as IToolbarFilter,
          ]
        : []),
    ],
    [isPrototype, t]
  );

  return toolbarFilters;
}
