import {
  LoadingPage,
  PageDetail,
  PageDetails,
  usePageAlertToaster,
  usePageNavigate,
} from '@ansible/ansible-ui-framework';
import { EmptyStateNoData } from '@ansible/ansible-ui-framework/components/EmptyStateNoData';
import { useClipboard } from '@ansible/ansible-ui-framework/hooks/useClipboard';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useClearCache } from '@ansible/common-ui/useInvalidateCache/useInvalidateCache';
import { Button, ClipboardCopy, Title } from '@patternfly/react-core';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useOutletContext, useParams } from 'react-router-dom';
import styled from 'styled-components';
import { HubError } from '../../common/HubError';
import { MarkdownEditor } from '../../common/MarkdownEditor';
import { hubAPI } from '../../common/api/formatPath';
import { hubAPIPut } from '../../common/api/hub-api-utils';
import { getContainersURL } from '../../common/utils/getContainersURL';
import { HubRoute } from '../../main/HubRoutes';
import { ExecutionEnvironment } from '../ExecutionEnvironment';

const ControlButtons = styled.div`
  display: flex;
`;

const EditButtonWrapper = styled.div`
  float: right;
`;

interface ReadmeType {
  updated_at: string;
  created_at: string;
  text: string;
}

export function ExecutionEnvironmentDetails() {
  const { t } = useTranslation();
  const { writeToClipboard } = useClipboard();
  const { id: paramId } = useParams<{ id: string }>();
  const { executionEnvironment } = useOutletContext<{ executionEnvironment?: ExecutionEnvironment }>();
  const id = paramId ?? executionEnvironment?.name;
  const pageNavigate = usePageNavigate();
  const alertToaster = usePageAlertToaster();
  const { clearCacheByKey } = useClearCache();

  const [markdownEditing, setMarkdownEditing] = useState(false);
  const [readme, setReadme] = useState<string>('');

  const readmeUrl = id
    ? hubAPI`/v3/plugin/execution-environments/repositories/${id}/_content/readme/`
    : undefined;

  const { data, isLoading, error, refresh } = useGet<ReadmeType>(readmeUrl);

  useEffect(() => {
    setReadme(data?.text ?? '');
  }, [data]);

  const saveMarkdown = async (name: string) => {
    try {
      await hubAPIPut<ReadmeType>(
        hubAPI`/v3/plugin/execution-environments/repositories/${name}/_content/readme/`,
        {
          text: readme,
        }
      );

      clearCacheByKey(hubAPI`/v3/plugin/execution-environments/repositories/`);
    } catch (error) {
      alertToaster.addAlert({
        variant: 'danger',
        title: (error as { details: string })?.details || t('Failed to save README file'),
        children: error instanceof Error && error.message,
      });
    }

    setMarkdownEditing(false);
  };

  if (isLoading || !id) {
    return <LoadingPage />;
  }

  if (error) {
    return <HubError error={error} handleRefresh={refresh} />;
  }

  const instructions =
    'podman pull ' +
    getContainersURL({
      name: id,
    });

  return (
    <PageDetails numberOfColumns={'single'}>
      <Title headingLevel="h2">{t('Instructions')}</Title>
      <PageDetail label={t('Pull this image')}>
        <ClipboardCopy
          data-cy="clipboard-copy"
          data-testid="clipboard-copy"
          hoverTip={t('Copy to clipboard')}
          clickTip={t('Successfully copied to clipboard!')}
          textAriaLabel={t('Copyable input')}
          toggleAriaLabel={t('Show content')}
          onCopy={() => {
            writeToClipboard(instructions ?? '');
          }}
          isReadOnly
        >
          {instructions}
        </ClipboardCopy>
      </PageDetail>
      <PageDetail label={(markdownEditing || readme) && t('README')}>
        {!markdownEditing && readme && (
          <EditButtonWrapper>
            <Button
              variant={'primary'}
              onClick={() => {
                setMarkdownEditing(true);
              }}
            >
              {t`Edit`}
            </Button>
          </EditButtonWrapper>
        )}
        {!markdownEditing && !readme ? (
          <EmptyStateNoData
            title={t`No README`}
            description={t`Add a README with instructions for using this container.`}
            button={
              <Button
                data-cy="add-readme"
                data-testid="add-readme"
                variant="primary"
                onClick={() => setMarkdownEditing(true)}
              >
                {t`Add`}
              </Button>
            }
          />
        ) : (
          <MarkdownEditor
            text={readme}
            placeholder={''}
            helperText={''}
            updateText={(value: string) => {
              setReadme(value);
            }}
            editing={markdownEditing}
          />
        )}
        {markdownEditing && (
          <ControlButtons>
            <div data-cy="save-readme" data-testid="save-readme">
              <Button
                variant={'primary'}
                onClick={() => {
                  void saveMarkdown(id);
                }}
              >
                {t`Save`}
              </Button>
            </div>
            <Button
              variant={'link'}
              onClick={() => {
                pageNavigate(HubRoute.ExecutionEnvironmentPage, { params: { id } });
              }}
            >
              {t`Cancel`}
            </Button>
          </ControlButtons>
        )}
      </PageDetail>
    </PageDetails>
  );
}
