import { IToolbarFilter, ToolbarFilterType } from '@ansible/ansible-ui-framework';
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';

export function useEeApprovalFilters() {
  const { t } = useTranslation();

  return useMemo<IToolbarFilter[]>(
    () => [
      {
        key: 'image_name',
        label: t('Image'),
        type: ToolbarFilterType.SingleText,
        query: 'image_name__icontains',
        comparison: 'contains',
      },
      {
        key: 'status',
        label: t('Status'),
        type: ToolbarFilterType.SingleSelect,
        query: 'status',
        options: [
          { label: t('Needs review'), value: 'needs_review' },
          { label: t('Approved'), value: 'approved' },
          { label: t('Rejected'), value: 'rejected' },
        ],
        placeholder: t('Select statuses'),
      },
      {
        key: 'signature_status',
        label: t('Signature status'),
        type: ToolbarFilterType.SingleSelect,
        query: 'signature_status',
        options: [
          { label: t('Signed'), value: 'signed' },
          { label: t('Unsigned'), value: 'unsigned' },
          { label: t('Unverified'), value: 'unverified' },
        ],
        placeholder: t('Select signature status'),
      },
    ],
    [t]
  );
}
