import { PageFormGroup } from '@ansible/ansible-ui-framework/PageForm/Inputs/PageFormGroup';
import {
  Button,
  Label,
  LabelGroup,
  TextInputGroup,
  TextInputGroupMain,
  TextInputGroupUtilities,
} from '@patternfly/react-core';
import TimesIcon from '@patternfly/react-icons/dist/esm/icons/times-icon';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';

export function FormChipsInput(
  props: Readonly<{
    label: string;
    labelHelp?: string;
    chips: string[];
    onChipsChange: (chips: string[]) => void;
    fieldId: string;
    placeholder?: string;
  }>
) {
  const { label, labelHelp, chips, onChipsChange, fieldId, placeholder } = props;
  const [inputValue, setInputValue] = useState('');
  const { t } = useTranslation();

  const addChips = () => {
    if (!inputValue.trim()) {
      return;
    }
    const nextChips = inputValue
      .split(',')
      .flatMap((chip) => chip.trim().split(' '))
      .map((chip) => chip.trim())
      .filter(Boolean);
    const uniqueChips = [...new Set([...chips, ...nextChips])];
    onChipsChange(uniqueChips);
    setInputValue('');
  };

  return (
    <PageFormGroup label={label} labelHelp={labelHelp} fieldId={fieldId}>
      <TextInputGroup>
        <TextInputGroupMain
          value={inputValue}
          onChange={(_event, value) => setInputValue(value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') {
              event.preventDefault();
              addChips();
            }
          }}
          id={fieldId}
          placeholder={chips.length === 0 ? (placeholder ?? t('Type a value and press Enter')) : undefined}
          aria-label={label}
        >
          {chips.length > 0 ? (
            <LabelGroup numLabels={8} aria-label={t('Selected values')}>
              {chips.map((chip) => (
                <Label
                  key={chip}
                  variant="outline"
                  onClose={() => onChipsChange(chips.filter((item) => item !== chip))}
                >
                  {chip}
                </Label>
              ))}
            </LabelGroup>
          ) : null}
        </TextInputGroupMain>
        {inputValue ? (
          <TextInputGroupUtilities>
            <Button
              icon={<TimesIcon aria-hidden />}
              variant="plain"
              onClick={() => setInputValue('')}
              aria-label={t('Clear input value')}
            />
          </TextInputGroupUtilities>
        ) : null}
      </TextInputGroup>
    </PageFormGroup>
  );
}
