import { PrototypeNote } from '../../../common/PrototypeNote';

export function ExecutionEnvironmentPrototypeNote({
  defaultOpen,
}: Readonly<{ defaultOpen?: boolean }> = {}) {
  return (
    <PrototypeNote
      defaultOpen={defaultOpen}
      notes={[
        <>
          Selecting an image auto-suggests the EE <strong>Name</strong> from the image path. Tag
          filters still use include/exclude chips; the first tag is pre-filled when creating from
          the registry Images tab.
        </>,
        <>
          Submit still posts to <code>/_ui/v1/execution-environments/remotes/</code> with{' '}
          <code>upstream_name</code> derived from the selected image. <strong>Upstream name</strong>{' '}
          is the image path inside the registry (e.g.&nbsp;<code>my-org/my-ee</code>) — the{' '}
          <strong>Image</strong> picker is the user-facing replacement for typing that path.
        </>,
        <>
          <strong>Tags</strong> are version labels on an image (<code>latest</code>,{' '}
          <code>2.6.0</code>, etc.). Include/exclude chips control which tags Hub syncs; the picker
          selects the image path only.
        </>,
        <>
          <strong>Labels</strong> (governance metadata) are separate from image tags. Multi-select on
          this form; chips on EE list and detail header. Mock values in demo — production would come
          from Hub settings.
        </>,
        <>
          <strong>Pull through Hub (Sep&nbsp;3):</strong> After sync, users pull via the{' '}
          <strong>Hub endpoint</strong>, not the external registry URL — same path Controller uses.
          The Image picker selects the upstream path; runtime pull commands should reference Hub.
        </>,
        <>
          <strong>Signature status</strong> is shown on the EE list and EE detail header.{' '}
          <strong>Sign execution environment</strong> is on the EE list/detail kebab. Signing reuses
          existing Hub Signature Keys flow; backend may move to Sequoia PGP per SDP.
        </>,
        <>
          <strong>UX recommendation (SDP Q21):</strong> Show signature mismatch as an explicit status
          label (Unverified / Verification failed), not hidden from lists.
        </>,
        <>
          <strong>UX recommendation:</strong> Hide images whose architecture is not supported on
          this platform from the Create EE image picker — users cannot run them in jobs, so showing
          them adds confusion. Full registry catalog remains on Registry &rarr; Images for browsing.
        </>,
      ]}
      questions={[
        'Should image picker support multi-tag subscription (sync all tags) vs single tag?',
        'Should long upstream image paths show a validation warning when they exceed downstream limits (e.g. EDA 150-character cap)?',
        'Should governance labels live only on the EE form, or should the Approve modal also set labels (e.g. reviewer must tag production at approval time)?',
      ]}
    />
  );
}
